pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Residuals below 10 are often unusable for the given item range (10-80)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: Reward bins that can accommodate the next item perfectly
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if the next item fits well in the remaining space
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if the next item cannot fit in this bin, but could have elsewhere
            score += 20.0;
        }
    }

    // Progression awareness: Towards the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold
    // to force it only when existing bins are poorly suited
    if bin_residual == bin_capacity {
        // Only open new if we have many bins already or if existing bins are too tight
        if open_bins_count > 0 && mean_residual > 20.0 {
            score -= 25.0;
        } else {
            score += 40.0;
        }
    }

    // Reward bins that bring the residual closer to the global mean (balancing)
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // If this is the only bin that fits the item, highly prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We penalize larger post_residuals heavily.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item,
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Reward cases where the resulting residual after the next item is near zero.
        let post_post = post_residual - next_item_size;
        score += post_post as f64 * 0.5;
    }

    // 3. Fragmentation Avoidance: If this is the only bin that fits the item,
    // we prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global Efficiency: If the current bin's residual is significantly above
    // the mean residual, it is likely "too empty" compared to others.
    // Penalize using bins that are significantly emptier than the average.
    if bin_residual as f64 > mean_residual + 15.0 {
        score += 20.0;
    }

    // 5. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only accept it if the current fit is catastrophic (post_residual > 60).
    if bin_residual == bin_capacity {
        if post_residual > 60 {
            score = 40.0; // Moderate score to allow new bin creation
        } else {
            score = 1000.0; // Heavily discourage opening new bins unless necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize larger post_residuals to keep bins tightly packed.
    let mut score = post;

    // Penalty for creating a "small" residual (the "dead space" trap)
    // If post_residual is between 1 and 9, it is highly unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item is large, avoid leaving a small residual now.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post < next_f {
            // High penalty if we create a gap that is too small for the next item
            score += (next_f - post) * 2.5;
        }
    }

    // Dynamic thresholding based on stream progress
    // As we near the end of the stream, we become more aggressive in packing
    // to avoid opening new bins unnecessarily.
    if fitting_bins_count > 0 {
        // If this is an existing bin, reduce score to favor reuse over new bins
        score -= (100.0 - mean_residual) * (1.0 - progress * 0.5);
    } else {
        // If this is a new bin, apply a progress-dependent cost
        // Opening a new bin is expensive early on, but necessary as we finish
        score += 40.0 * (1.0 - progress);
    }

    // Coupling with open_bins_count to prevent excessive fragmentation
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic: Best-fit-decreasing logic with a penalty for leaving "dead space" that cannot fit the next item.

    let mut score = post_residual as f64;

    // 1. Reward tight packing: If post_residual is exactly 0, prioritize this bin heavily.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Lookahead matching: If the next item fits into the post_residual, reward this bin.
    // This effectively implements a "Best-Fit" variation that keeps future items in mind.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 200.0 + (post_residual - next_item_size) as f64;
    }

    // 3. Penalty for "dangerous" residual: If the residual is too small for any likely item (e.g., < 10),
    // it creates "dead space". Penalize this, but only if it's not a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 4. Global state awareness: If we are near the end of the stream, prioritize closing bins
    // by penalizing the creation of new bins (represented by the empty bin case).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have existing options, 
        // mitigated as the stream progresses to ensure we don't end with many half-empty bins.
        score += 80.0 * (1.0 - progress);
    }

    // 5. Mean-residual alignment: Penalize bins that deviate significantly from the mean,
    // to keep the packing density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Last-chance logic: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // Already established by base score.

    // 2. Lookahead Integration: If next_item_size is large, avoid leaving small residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot accommodate the next item if it's large
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a bin that can fit the next item perfectly (or nearly so)
            let fit_slack = post_residual - next_item_size;
            score -= (100.0 / (fit_slack as f64 + 1.0));
        }
    }

    // 3. Global State: Discourage opening new bins early unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the mean residual is already too tight (fragmentation risk)
        // or if we are near the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        let openness_factor = (open_bins_count as f64) / 10.0;

        score += 40.0 * (1.0 - progress);
        score += mean_residual * 0.5;
        score -= openness_factor * 5.0;
    }

    // 4. Criticality: If this is the only bin that fits, prioritize it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Fragmentation Avoidance: Penalize residuals that are too small to be useful (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if current bins are very fragmented
    let mut score = post_residual as f64;

    if is_new_bin {
        // Only open a new bin if the average residual is already high (fragmentation) 
        // or if we have no other choice, or if we are nearing the end of the stream
        let threshold = 30.0 + (progress * 40.0) - (mean_residual * 0.5);
        score = if fitting_bins_count == 0 { 0.0 } else { threshold };
    } else {
        // Best Fit Decreasing logic: prioritize bins that leave the least space
        // Add a penalty for leaving "unusable" space (e.g., < 10, which is the minimum item size)
        if post_residual > 0 && post_residual < 10 {
            score += 50.0; 
        }

        // Lookahead: if the next item can fit into the post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Global state: if we have many open bins, prioritize tightening the most fragmented ones
        if open_bins_count > 5 {
            score += (mean_residual - post_residual as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot fit common items)
    // We penalize residuals that are non-zero but smaller than the minimum expected item size (approx 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic lookahead coupling: 
    // If the next item is large, favor bins that preserve space for it (or fit it perfectly).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize bins that leave just enough space to be unusable for the next item
            score += (100.0 - post_residual as f64) * 0.2;
        }
    }

    // 3. Pressure management:
    // If we have few fitting bins, we are nearing a "new bin" event. 
    // Bias towards filling the most constrained bins first (Best Fit).
    if fitting_bins_count > 0 {
        score += (bin_residual as f64) * 0.5;
    }

    // 4. New bin threshold logic:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We only open a new bin if the current mean_residual is very high (indicating poor packing).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Apply a significant barrier to opening new bins unless the existing bins are inefficient
            score = mean_residual * 1.5;
        }
    }

    // 5. Modulo-based "Perfect Fit" reward:
    // Reward bins that lead to a residual that is a multiple of 20 (favorable for packing 20, 40, 50, etc.)
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit principle).
    // We penalize high post_residual quadratically to favor tight packing.
    let mut score = post_res_f * post_res_f;

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it.
    // If next_item_size is 0 (end of stream), we prioritize closing bins (lower post_residual).
    if next_item_size > 0 {
        let fit_margin = post_res_f - next_item_size as f64;
        if fit_margin < 0.0 {
            // Penalty for stranding the next item: avoid leaving space that fits nothing.
            score += 500.0 * (fit_margin.abs());
        } else {
            // Reward bins that can accommodate the next item comfortably.
            score -= 150.0 * (1.0 / (fit_margin + 1.0));
        }
    }

    // Dynamic Thresholding: As the stream progresses, be more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (wasteful packing).
        // Scale the cost of a new bin by the progress to prevent late-stage fragmentation.
        let new_bin_cost = 2500.0 * (1.0 + progress) - (mean_residual * 10.0);
        score += new_bin_cost;
    } else {
        // If it's an existing bin, favor those that move the bin toward a "full" state.
        // We use the fitting_bins_count to prioritize filling near-full bins.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    // Interaction term: Penalize deviations from the mean to encourage uniform packing density.
    let deviation = (post_res_f - mean_residual).abs();
    score += 50.0 * (deviation * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit), but penalize fragmentation based on lookahead 
    // and global bin utilization to decide when to open a new bin.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: the remaining space (smaller is better).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill).
    // If the post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 3. New Bin Threshold: Only open a new bin if the current bin's post_residual 
    // is highly suboptimal (e.g., > 40) or if we are forced to by fitting_bins_count.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin.
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of existing bins is already very low
            // or if we are at the very end of the stream.
            let willingness = (mean_residual / bin_capacity as f64) * (1.0 - progress);
            score = 50.0 + (40.0 * (1.0 - willingness));
        }
    } else {
        // 4. Global state adjustment: If open_bins_count is high, prioritize filling 
        // existing bins to reduce the total count.
        score += (open_bins_count as f64) * 0.5;

        // Penalize bins that deviate far from the mean residual to keep bin levels balanced.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we apply
    // non-linear penalties to avoid leaving small, unusable gaps.
    // Penalty for creating 'dead space': gaps < 10 are often unusable for the given range (10-80).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large and the current placement
    // leaves little room, penalize the placement to keep the bin open for the next item.
    let lookahead_penalty = if next_item_size > 0 && (post as u32) < next_item_size && post > 0.0 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Progress-based scaling: As the stream nears the end, become more aggressive 
    // about filling bins (Best Fit) rather than opening new ones.
    let end_game_factor = 1.0 - progress;

    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We penalize this heavily unless the open bins are already very full.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Only open new bins if existing bins are already quite full (e.g., > 70% average)
        if open_bins_count > 0 && avg_fill > 0.7 {
            10.0 * end_game_factor
        } else {
            100.0 * (1.0 + progress)
        }
    } else {
        0.0
    };

    // Combine factors:
    // 1. Prioritize smaller post_residual (Best Fit)
    // 2. Add penalties for dead space and poor lookahead matches
    // 3. Add dynamic cost for opening new bins
    post + dead_space_penalty + lookahead_penalty + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tight.
    // 2. New bin thresholding: Only open a new bin if the best-fit is extremely poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: only do it if existing bins are nearly full.
        // As we progress through the stream, become more conservative about opening new bins.
        score = 25.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // If this is the only bin that fits, we are forced to pick it; prioritize it highly.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead: If the next item is large, avoid leaving a residual that is too small to be useful.
        // We define 'useful' space as >= 20. If post_residual is in (0, 20), it's 'dead space'.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += 40.0; // Heavy penalty for creating unfillable gaps
            }

            // If the next item fits perfectly in the remaining space, reward this placement.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        }

        // Global state: If we have many open bins, prioritize filling the ones with the least residual.
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit: Penalize larger post_residuals to keep bins tightly packed.
    // 2. Lookahead: If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Further reward if it creates a "perfect fit" for the upcoming item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. New Bin Penalty: If bin_residual == bin_capacity, we are considering opening a new bin.
    // Only do this if we are desperate (no good fit found) or if the current bin count is low.
    if bin_residual == bin_capacity {
        score += 55.0; // Base cost for opening a new bin
        // Reduce penalty if we have very few bins open to encourage parallel filling
        score -= (open_bins_count as f64 * 2.5);
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly worse than the average.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item, 
    // prioritize it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress Scaling: As we near the end of the stream, prioritize closing bins
    // by tightening the requirements for new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We add a non-linear penalty for creating "dead space" (post_residual < 10) 
    // unless it's a perfect fit (post == 0).
    let mut score = post * 1.5;
    if post > 0.0 && post < 10.0 {
