    // about filling bins tightly to avoid trailing waste.
    score += (open_bins_count as f64 * 2.0) * progress;

    // Favor bins that have a residual close to the current mean_residual 
    // to maintain uniformity across bins (reduces fragmentation).
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Special handling for new bin (bin_residual == bin_capacity):
    // Only open if the existing fits are all suboptimal (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high, but decreases slightly 
        // if we are early in the stream or if fits are poor.
        score = 65.0 - (progress * 10.0);
    }

