    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: If the next item is large and the current post_residual 
    // is too small to accommodate it, penalize this choice.
    if next_item_size > 0 {
