            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Incentive for consolidating: If this is the only bin that fits, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
