    }

    // New bin threshold control: 
    // When deciding to open a new bin (bin_residual == bin_capacity),
    // make it expensive relative to the mean residual of current bins.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
        // As the stream progresses, we become more conservative about opening new bins.
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // We aim to minimize the residual space (Best Fit), but penalize small gaps that are hard to fill.
    // A gap of 1-9 is often "dead space" because min item size is 1.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
