    };

    base_score + gap_penalty + lookahead_penalty + efficiency_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    // We penalize small post_residuals (creating "slivers") unless we are near the end of the stream.
    // Penalty is scaled by the probability of the next item fitting into the created gap.
    let sliver_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 - progress) * 2.0
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large, avoid bins that leave just enough space 
    // to be "almost" full but not enough for the next item.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Global state awareness: If we have many open bins, prioritize packing into the tightest ones.
    // As progress increases, we become more aggressive in closing bins (lower score for lower post_residual).
    let density_factor = (open_bins_count as f64 / 10.0) * progress;

    // New bin threshold control: 
    // If bin_residual == bin_capacity, this is a new bin.
    // We penalize opening a new bin heavily unless the current open bins are very poorly utilized.
    let score = if res == bin_capacity as f64 {
        let avg_waste = bin_capacity as f64 - mean_residual;
        // Only open new if the average waste in existing bins is high, or if we have no fitting bins.
        if fitting_bins_count == 0 {
            10.0 // Base cost of opening a new bin
        } else {
            10.0 + (avg_waste * 0.5) + (progress * 20.0)
        }
    } else {
        post + sliver_penalty + lookahead_penalty + (density_factor * post)
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead zones" (small remainders that are hard to fill).
    // An ideal remainder is 0, followed by values larger than the largest common item (80).
    // We use a quadratic penalty for remainders in the range [1, 25] to discourage fragmenting.
    let dead_zone_penalty = if post_residual > 0 && post_residual <= 25 {
        (25.0 - post_res).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, we prefer larger post_residuals now.
    // Otherwise, we prioritize Best Fit (minimizing post_residual).
    let lookahead_factor = if next_item_size > 60 {
        -1.5 * (next_item_size as f64 / bin_capacity as f64) * post_res
    } else {
        0.5 * post_res
    };

    // Global state awareness: encourage using existing bins as the stream nears the end,
    // to avoid leaving partially filled bins stranded.
    let completion_bias = (1.0 - progress) * (open_bins_count as f64 * 5.0);

    // New bin candidate logic:
    // If this is a new bin (bin_residual == bin_capacity), score it based on 
    // the current density of open bins. We only open a new bin if the existing
    // fits are truly poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty to open new bin unless density is very low
        150.0 + (open_bins_count as f64 * 2.0) - (progress * 20.0)
    } else {
        // Existing bin score:
        // Combine the post-fit remainder, lookahead, and dead-zone avoidance.
        post_res + dead_zone_penalty + lookahead_factor + completion_bias
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to discourage early waste
    // and rewards opening new bins late in the stream if necessary.
    if is_new_bin {
        score += 15.0 + (progress * 25.0);
    }

    // Penalty for "bad" fits: If the remaining space is small but unusable,
    // we penalize it quadratically.
    if !is_new_bin && post_residual > 0 {
        let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score += (tightness * 10.0).powf(2.0);
    }

    // Lookahead logic: If the next item exists, penalize bins that can't fit it
    // or favor bins that leave enough space for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= 5.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Pressure factor: if only one bin can fit the item, we are forced to use it.
    // If fitting_bins_count is low, we reduce the score to ensure we don't open a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Interaction with mean_residual to keep bins balanced
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

