    if post_res > 0.0 && post_res < 10.0 {
        score += 50.0 * (10.0 - post_res);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_res >= next_item_size as f64 {
        score -= 25.0 * (next_item_size as f64 / 100.0);
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // force more aggressive consolidation by penalizing new bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Increase penalty for opening new bins as the stream progresses
        score += 15.0 + (30.0 * progress);

        // If we are late in the game, penalize new bins even more to force packing
        if progress > 0.8 {
            score += 40.0;
        }
    }

    // Coupling: If we have many open bins, penalize opening new ones.
    // If we have few, prioritize filling the existing ones.
    score += (open_bins_count as f64) * 0.5;

    // Favor bins that are closer to the mean residual to maintain uniform packing density
    let residual_diff = (post_res - mean_residual).abs();
    score += 0.2 * residual_diff;

    // Final scaling: favor bins that leave more room for future items 
    // if we are in the early stages, but favor tight fit (low post_res) 
    // in late stages.
    score += (post_res * progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in range [1, 9], it's a "dead zone" for most items (min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current best fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open new if we have many open bins already or if the average residual is very low
        // (meaning existing bins are already "tight" and hard to fit large items into).
        score += 25.0; 
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 2.0;
        }
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Global Balance: As the stream progresses, favor packing tighter to minimize late-stage bin creation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Harmonic Class Logic: Prefer bins that leave space for common item sizes (e.g., 25, 33, 50).
    // These are divisors of the capacity (100).
    let rem = post_residual % 25;
    if rem == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range (0, 10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: Reward placements that leave room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize creating a bin that cannot accommodate the lookahead item
            score += 20.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones are available
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit the item, penalize heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Density Balancing: Prefer bins that stay close to the current mean residual
    // This helps keep bins packed at similar levels to avoid fragmented capacity
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression weighting: As the stream nears completion, prioritize clearing open bins
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
