    }

    // Lookahead synergy: If the next item can fit in the post_residual, 
    // we reward this placement to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Harmonic class logic: Reward bins that align with the mean_residual
    // to keep the distribution of bin states uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the penalty for fitting into existing bins is extremely high.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Heavily penalize opening a new bin unless existing bins are very poor fits
            score += 65.0 + (fitting_bins_count as f64 * 5.0);
        }
    }

    // Progression weight: As we near the end of the stream, prioritize 
    // tighter packing (lower residuals) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable gaps.
    // If post_residual is < 10, it's likely "dead space" as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit into the new post_residual,
    // reward this bin choice to consolidate items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already active,
    // unless the fit is perfect (post_residual == 0).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Efficiency Bias: Favor bins that stay close to the current mean residual
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Final Fit Optimization: If this is the only bin that fits the item,
    // lower the score to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Tight Fit Bonus: Reward filling the bin as much as possible.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

