pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range is often wasted)
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        15.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward tighter fits, but weight by progress to be more aggressive early on
    let tightness_score = post_res + (post_res.powf(1.5) * progress);

    // Lookahead logic: if next_item fits in current post_residual, prioritize this bin
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is the only bin that fits the item, make it highly attractive to avoid new bin creation
    let necessity_bonus = if fitting_bins_count == 1 {
        -50.0
    } else {
        0.0
    };

    // Discourage opening new bins (bin_residual == bin_capacity) unless necessary
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Combine factors
    tightness_score + fragmentation_penalty + lookahead_bonus + necessity_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space that is too small for common items (below 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic alignment: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    // This reduces the likelihood of leaving "dead" space that cannot be filled later.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // 3. Lookahead logic: If a next item is known, penalize residuals that can't fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward residuals that are perfect fits for the next item
            score -= (100.0 - (post_residual as i32 - next_item_size as i32).abs() as f64) * 0.1;
        }
    }

    // 4. Scarcity/Pressure: If this is the last fitting bin, prioritize it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. New Bin thresholding: Make opening a new bin expensive unless the current fit is terrible
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (bins are empty)
        // or if we have very few bins open.
        score += 35.0 + (mean_residual * 0.2);
    }

    // 6. Progressive packing: As we near the end of the stream, tighten requirements
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
