            score += 15.0 * (1.0 - progress);
        }
    }

    // Progression Weighting:
    // As the stream nears the end, prioritize closing bins (lower mean_residual)
    // over opening new ones.
    if fitting_bins_count > 0 {
        // If it's a new bin, apply a progress-dependent opening cost.
        if bin_residual == bin_capacity {
            score += 20.0 + (30.0 * progress);
        }
    } else {
        // Force opening if no bins fit.
        score -= 100.0;
    }

    // Non-linear coupling with mean_residual:
    // Favor bins that align with the global average to keep packing density uniform.
    let dev = (post - mean_residual).abs();
    score += 0.5 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: punish larger residuals to keep bins tightly packed.
    // We normalize by capacity to create a cost surface.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2. Harmonic/Modulo logic: prioritize post_residuals that are multiples of common item sizes (20, 25, 33).
    // This creates "shelves" that are more likely to accommodate future items.
    let harmonic_penalty = match post_residual {
        r if r % 25 == 0 => -5.0,
        r if r % 20 == 0 => -3.0,
        r if r % 10 == 0 => -1.0,
        _ => 2.0,
    };
    score += harmonic_penalty;

    // 3. Lookahead logic: if the next item fits perfectly in the new residual, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave enough space for the next item without being overly fragmented.
            score -= 5.0;
        } else {
            // Penalize creating a bin that cannot fit the next item if it's large.
            if next_item_size > 50 {
                score += 15.0;
            }
        }
    }

    // 4. Strategic new-bin avoidance: 
    // If we are forced to pick a bin and it's the only one left, discourage opening a new one
    // unless the fit is truly abysmal.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // High penalty for opening a new bin if we have existing capacity.
        score += 40.0;

        // If the stream is nearly finished, favor opening a new bin less.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Balance distribution: avoid creating too many bins by penalizing high open_bins_count.
    score += (open_bins_count as f64) * 0.5;

    // 6. Final adjustment: bias towards filling bins that are already partially full (high mean_residual).
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
