    }

    // 3. Harmonic awareness: Prefer residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "slots" for future items.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.5;

