    // 5. New bin handling: Only open a new bin if the current best existing bin is poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many bins open or if current options are bad.
        // We penalize opening new bins to encourage packing into existing ones.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    } else {
