    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (high fragmentation) 
        // or if it's the only way to avoid a very poor fit.
        score += 25.0; 
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 2.0;
        }
    }

    // 4. Fragmentation Control: Penalize placements that make the bin's residual deviate 
    // significantly from the population mean of residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. Last Chance Logic: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive Tightening: As the stream nears the end, increase the 
    // penalty for opening new bins to force consolidation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
