    // We heavily penalize residuals between 1 and 9 (near-unusable space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic lookahead: If the current post_residual can fit the next item, 
    // reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic class logic: Favor bins that leave room for specific item-size classes
    // (e.g., leaving space for items of size 25, 33, or 50).
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // 4. Global state pressure: If open_bins_count is high, be more aggressive about 
    // filling current bins even if it results in slightly suboptimal post_residuals.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.2;
