    // 4. Tight Fit Reward: Strongly favor bins that result in near-zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean_residual
    // to keep the filling distribution balanced across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for empty bins to discourage premature bin opening
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Best-Fit logic: punish large post_residuals (wasted space)
    // We want to minimize post_residual to keep space tight.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead Matching: If the next item fits into the post_residual, 
    // highly prioritize this bin (rewarding tight packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    }

    // 4. Mean Residual Balancing: If the post_residual is significantly 
    // smaller than the current mean, we are creating a "bottleneck" bin.
    // Discourage creating bins that are significantly tighter than the average.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // 5. Last Chance Awareness: If this is the only bin that fits the current item,
    // we must take it regardless of fit quality to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progressive tightening: As the stream progresses, prioritize filling 
    // existing bins more aggressively to avoid trailing under-utilized bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments
    // Fragments < 10 are often "dead space" that cannot fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Reward creating a perfect fit for the lookahead
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // 3. New Bin Thresholding: Prevent opening new bins too early.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost based on remaining items.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other options exist, decreasing as we near end of stream
        score += 60.0 * (1.0 - progress);
        // If we have plenty of open bins, penalize opening more
        score += open_bins_count as f64 * 2.0;
    }

    // 4. Global State Balancing: Avoid creating bins that deviate significantly from the mean residual.
    // This keeps the packing density uniform across all bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Scarcity/Fitting Logic: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

