    let mut score = post;

    // Penalty for creating 'dead zones' (small residuals that are unlikely to fit future items)
    // We define a dead zone as post_residual < 20. 
    // We scale this penalty by the progression of the stream.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: If the next item is large and the current post_residual 
    // is too small to accommodate it, penalize this choice.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
