    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Dynamic penalty for opening new bins:
    // When residual == capacity, this is a new bin. 
    // We penalize opening new bins more heavily as we approach the end of the stream (progress -> 1.0)
    // to force consolidation.
    if bin_residual == bin_capacity {
