    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Reward perfect fits heavily
    if post_residual == 0 {
        score -= 20.0;
    }

    // Pressure factor: if this is a new bin, penalize it relative to the number of existing open bins
    // to encourage filling existing bins before fragmenting space.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have very few open bins, opening a new one is less catastrophic.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if a next item exists, penalize bins that cannot fit it after placing the current item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Favor bins that are closer to the mean residual to maintain uniform bin usage
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // If this is the last chance to fit the item in an existing bin, reduce penalty to avoid unnecessary new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are rarely useful for items 10-80)
    if post_residual > 0 && post_residual < 10 {
