    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 6. Penalty for opening a new bin:
    //    If bin_residual == bin_capacity, this represents the "New Bin" candidate.
    //    We only want to open a new bin if the current open bins result in very poor fits.
    if bin_residual == bin_capacity {
