    // 2. Harmonic Lookahead: If next_item_size fits in post_residual, reward this bin
    // This reduces fragmentation by pairing items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Harmonic Thresholding: Penalize "near-empty" space that doesn't fit common item sizes (harmonic classes)
    // If post_residual is small but not zero, it's often a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. New Bin Policy: Only open a new bin if the current fit is extremely poor
    // If this is a new bin (bin_residual == bin_capacity), score it based on the global state
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low
        // This is a "resistance" factor to opening new bins unnecessarily.
        score = 85.0 + (open_bins_count as f64 * 0.5);
    } else {
        // 5. Fitting Constraint: If this is the only bin that fits, prioritize it
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Progressive tightening: As the stream nears the end, become more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": gaps smaller than the smallest likely item (e.g., < 10)
    // are highly undesirable unless the gap is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. If this bin is the only one that fits, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 3. Lookahead: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 4. Pressure: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= open_bins_count as f64 * 0.5;
    }

    // 5. If considering a new bin (bin_residual == bin_capacity), penalize it based on
    // how many other bins are already available to accept the current item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;

        // Discourage opening a new bin if we have many open bins already.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Prefer packing items into bins that are already "tight" (low mean_residual).
    if mean_residual < 30.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (the "fragmentation" trap).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 space or large enough space for future items.
        if gap_after_next == 0.0 {
            score -= 40.0;
        } else if gap_after_next >= 10.0 {
            score -= 15.0;
        }
    }

    // 3. Global Packing Efficiency: If this bin is a new bin, penalize it relative to how many 
    // bins are already open and how much space is currently being wasted on average.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already quite tight,
        // or if we have very few open bins (avoiding fragmentation).
        score += (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    } else {
        // If we are placing in an existing bin, favor bins that are closer to the mean residual
        // to keep the "level" of packing consistent across open bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Urgency: As we near the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. Last chance protection: If this is the only bin that fits the current item, 
    // heavily incentivize using it to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals (the "Perfect Fit" reward is implicit in minimizing post_residual, 
    // but we must penalize "near-perfect" gaps that are too small to fit anything).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Global Density Management: If we have many open bins, prioritize filling the ones with the lowest residuals 
    // to keep the "average fragmentation" low.
    if open_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Thresholding: Discourage opening new bins unless the current bin is truly terrible or the remaining 
    // space is insufficient for the immediate future.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only pick this if the average residual is already very high (bins are mostly empty)
        // or if we are nearing the end of the stream.
        score += 30.0 + (mean_residual * 0.2) - (progress * 15.0);
    } else {
        // If this is the last fitting bin, prioritize it to avoid opening a new one prematurely.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, prioritize space utilization over bin consolidation.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (dead space < 10)
    // We treat 0 as perfect, but gaps between 1-9 are highly undesirable.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        100.0 / (post_res + 1.0)
    } else {
        0.0
    };

    // Interaction between next_item_size and current placement.
    // If next_item can fit in post_residual, reward the placement.
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else if next_item_size > post_residual && post_residual < 20 {
        // High penalty if we block a potential fit for the next item by creating a small gap
        15.0
    } else {
        0.0
    };

    // Favor filling bins closer to the mean residual to keep distribution uniform
    let balance_factor = (post_res - mean_residual).abs() * 0.1;

    // Discourage opening new bins (bin_residual == bin_capacity) unless necessary.
    // As the stream progresses, we become more conservative about opening new bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 + progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Nonlinear scaling of the post_residual:
    // We want to minimize post_residual (Best Fit), but with a quadratic curve 
    // to flatten the difference between "good" fits and "great" fits.
    let base_score = post_res.powf(1.5);

    base_score + dead_space_penalty + lookahead_reward + balance_factor + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic 206: Harmonic-Residual Balancing
    // We aim to minimize the post_residual, but heavily penalize values that prevent 
    // accommodating the next_item_size or creating "dead" zones (sizes < 10).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: If post_residual is small but not zero, it is often a "dead zone".
    // Penalize narrow gaps that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: If the next item cannot fit in this post_residual, 
    // penalize this bin choice to encourage keeping the bin open for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Efficiency Threshold: If this is the only bin that fits the item (fitting_bins_count == 1),
    // heavily reward it to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 4. Global Load Balancing: If we have many open bins, penalize opening a new one
    // (identified by bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Harmonic Smoothing: Adjust by deviation from mean_residual to favor bin consolidation.
    // If this bin's post_residual is significantly better than the global mean, reward it.
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
