    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic:
    // If we have a next_item, we want to see if the current post_residual 
    // can accommodate it. If post_residual >= next_item_size, we reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // 4. Mean-Residual Balancing:
    // If this bin's residual is significantly lower than the mean of all open bins,
    // we want to preserve it for future items (avoid making it too tight).
    // If it's higher than the mean, we want to fill it up to bring the average down.
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    } else {
        score -= 5.0;
    }

    // 5. New Bin Thresholding:
    // If this is an empty bin (new bin candidate), we only pick it if the 
    // penalty for using existing bins is high.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting 
        // into existing bins creates significant waste.
        score = 65.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Last-Chance Logic:
    // If fitting_bins_count == 1, this is the only bin that can take this item.
    // We should aggressively lower the score to ensure we don't open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals that create "dead space" (e.g., 1-5 units left)
    // We want to avoid small gaps that are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Efficiency: If many bins are open, be more aggressive about packing tightly (Best-Fit).
    // If few bins are open, allow more slack to preserve bin count.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += density_factor * 15.0;
    }

    // 4. Strategic Opening: When considering a brand-new bin (bin_residual == bin_capacity),
    // only choose it if the existing fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item,
            // unless we are at the very end of the stream.
            score += 60.0 * (1.0 - progress);
        } else {
            // If no other bin fits, this is mandatory.
            score = 0.0;
        }
    } else {
        // 5. Last Resort Logic: If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Final scaling for non-linear preference towards medium-sized residuals
    // (tending to keep bins somewhat balanced)
    score += (post_residual as f64).powf(1.1) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space": residuals below 10 are often unfillable
    // since items are >= 10. We penalize post_residuals in (0, 10).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if we have a next item, check if it fits in the current post_residual
    if next_item_size > 0 {
