    // Progression logic: As the stream nears the end, become more aggressive 
    // about filling bins to reduce the total count.
    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is the only bin that fits the item, highly prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Calibration for the "New Bin" candidate:
    // When bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current open bins are "too full"
    // to accept future items effectively.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin
        score = 45.0 + (mean_residual * 0.2);

        // If we still have many items, discourage opening new bins too early
        score += (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
