pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit approach).
    // We penalize small residuals (fragmentation) by applying a non-linear penalty for "near-full" bins.
    // If post_residual is very small (< 10), it creates "dead space" that is hard to fill.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(1.5)
    } else {
        0.0
    };

    // Incorporate the lookahead: if next_item_size fits in the current post_residual,
    // we reward this bin heavily to increase packing density.
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // If we are late in the stream (high progress), we become more aggressive about filling existing bins
    // to avoid opening new ones. We penalize using a new bin (bin_residual == bin_capacity)
    // proportional to the current progress.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 * (1.0 + progress)
    } else {
        0.0
    };

    // If fitting_bins_count is 1, this is the only bin that can hold the item. 
    // We should favor this bin unless the residual is extremely poor.
    let last_chance_adjustment = if fitting_bins_count == 1 && !is_new_bin {
        -15.0
    } else {
        0.0
    };

    // Coupling mean_residual: if the current bin's post_residual is significantly 
    // better than the mean, we bias towards it.
    let mean_coupling = (post - mean_residual).tanh() * 5.0;

    post + fragmentation_penalty + lookahead_bonus + new_bin_penalty + last_chance_adjustment + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
