    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low,
        // suggesting existing bins are too full to be efficient.
        if mean_residual < 20.0 && open_bins_count > 0 {
            score += 100.0; // Heavily penalize opening a new bin if existing ones have space
        } else {
            score -= 10.0; // Slight bias to open a new bin if we are running out of options
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64);

    // 6. Final adjustment for fitting_bins_count:
    // If this is the only bin that can fit the item, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit common small items (e.g., < 15),
    // it creates "fragmentation". We penalize post_residual values in the [1, 14] range heavily.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 12.0;
