    // 4. Tightness Reward: Favor bins that are already quite full (Best Fit behavior).
    // The smaller the post_residual, the better, unless it enters the "dead space" range.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive with fitting items into existing spaces.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items)
    // If the post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
