    }

    // 3. Balance usage: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 4. Tightness objective: Favor bins that leave the residual closer to the mean_residual
    // of other bins, promoting uniform fullness across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Critical thresholding: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progress weighting: As the stream progresses, be more conservative about 
    // leaving space, as fewer items remain to fill the gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit), but penalize fragmentation based on lookahead 
    // and global bin utilization to decide when to open a new bin.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: the remaining space (smaller is better).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill).
    // If the post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 3. New Bin Threshold: Only open a new bin if the current bin's post_residual 
    // is highly suboptimal (e.g., > 40) or if we are forced to by fitting_bins_count.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin.
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of existing bins is already very low
            // or if we are at the very end of the stream.
            let willingness = (mean_residual / bin_capacity as f64) * (1.0 - progress);
            score = 50.0 + (40.0 * (1.0 - willingness));
        }
    } else {
        // 4. Global state adjustment: If open_bins_count is high, prioritize filling 
        // existing bins to reduce the total count.
        score += (open_bins_count as f64) * 0.5;

        // Penalize bins that deviate far from the mean residual to keep bin levels balanced.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
