pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for creating "slivers" (dead space < 10) that are unlikely to be filled.
    // We increase score (penalize) as post_residual approaches 0, but only if it's too small for future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    // If next_item_size > post_residual, this bin will likely be unusable for the next step.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As we near the end of the stream, prioritize closing bins (lower mean_residual)
    // to avoid leaving many half-empty bins open.
    let residual_utilization_penalty = (post - mean_residual).abs() * progress;
    score += residual_utilization_penalty;

    // If this is a new bin (bin_residual == bin_capacity), calculate a threshold to avoid
    // opening it unless all other options are poor.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream.
        // We only open if fitting_bins_count is low or current fits are extremely poor.
        score += 25.0 * (1.0 - progress);

        // If we have many open bins already, discourage adding more.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward for using existing bins that have a residual close to the item size (tighter fit).
        // This is a non-linear interaction between fit quality and current stream progress.
        score -= (1.0 / (post + 1.0)) * 10.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Harmonic Class logic: prioritize filling bins to specific thresholds (e.g., 50, 33, 25)
    // to keep space for future items that fit into the remaining fractions.

    // Penalize creating "fragmented" space that is too small for common items (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is not enough for next_item_size, we penalize the current placement 
    // unless it results in a near-perfect bin fill.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward keeping space for the next item
            score -= 15.0;
        }
    }

    // Harmonic Class heuristic: 
    // If we have very few fitting bins, we are forced to pick one.
    // If we have many, we prioritize those that leave the bin "cleaner" (post_residual as a multiple).
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty;

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // Global progression: as the stream nears the end, become more aggressive 
    // about filling bins to reduce the number of open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // Prefer bins that are closer to the mean_residual to keep bin distribution uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (residual < 10) that cannot fit any future items (min size 10).
    // If post_residual is small but > 0, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Penalize opening new bins when existing options are available.
    // We heavily penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // proportional to the number of existing open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead optimization: If a future item exists, prioritize bins that 
    // leave enough room for that item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that block the next item from fitting here
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item
            score -= 10.0;
        }
    }

    // 4. Balance the fill rate: Encourage filling bins closer to capacity,
    // but avoid creating "micro-gaps" that are too small to be useful.
    // If post_residual is exactly 0, it is a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global pressure: As the stream progresses, prioritize closing bins
    // by being more aggressive with current fits.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space.
    // If we are opening a new bin (bin_residual == bin_capacity), penalize based on item size to force efficiency.
    if bin_residual == bin_capacity {
        score += 50.0 + (item_size as f64 * 0.5);
    }

    // 2. Lookahead Synergy: If next_item_size fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits for the upcoming item.
        score -= (100.0 - diff) * 0.8;
    }

    // 3. Mean Residual Balancing: Avoid creating bins that deviate significantly from the current average.
    // This helps keep future bin capacities consistent.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity Constraint: If this is the last bin that can fit the item, prioritize it to avoid 
    // fragmenting bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Scaling: As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress (late game, favor efficiency)
    if is_new_bin {
        score += 25.0 * (1.0 - progress * 0.5);
        // If other bins could fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward tight fits: if post_residual is very small, we leave less fragmentation
        // We favor bins that result in residuals close to the mean_residual of other bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // prioritize this bin to prepare for a "double-pack"
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Penalty for creating "orphan" space (too small to fit common items)
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Global state adjustment: reduce score if we have too many open bins, forcing consolidation
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We add a non-linear penalty for creating "dead space" (post_residual < 10) 
    // unless it's a perfect fit (post == 0).
    let mut score = post * 1.5;
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: If next_item_size is large, prioritize bins that 
    // can accommodate it. Penalize bins that leave too little space for the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 40.0 * (1.0 - (post / next_item_size as f64));
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing waste.
    score += (open_bins_count as f64 * 2.0) * progress;

    // Favor bins that have a residual close to the current mean_residual 
    // to maintain uniformity across bins (reduces fragmentation).
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Special handling for new bin (bin_residual == bin_capacity):
    // Only open if the existing fits are all suboptimal (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high, but decreases slightly 
        // if we are early in the stream or if fits are poor.
        score = 65.0 - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is in [1, 19], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 + (20.0 - post_residual as f64) * 2.5;
    }

    // 2. Lookahead optimization: If next_item_size fits in the current post_residual,
    // prioritize this bin heavily to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
        // Reward tighter fits for the lookahead item.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Harmonic class awareness: Penalize bins that leave residuals near 
    // the capacity/2 or capacity/3 boundaries, which are often "awkward" 
    // for future items.
    let residual_mod = post_residual % 25;
    if residual_mod < 5 {
        score += 15.0;
    }

    // 4. Strategic new bin control:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have options.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other option, make it attractive.
            score -= 10.0;
        }
    }

    // 5. Global progression adjustment:
    // As we approach the end of the stream, prioritize closing bins 
    // (smaller post_residual) to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to be useful
    // (typically < 10, as the minimum item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when capacity exists.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of open bins is very low or no other options exist.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Optimization: If next_item_size is large, avoid bins that leave
    // insufficient room for it, effectively trying to preserve space for future items.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 30 {
        score += 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item,
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better 
    // than the mean residual of all open bins, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score to place item.
    // post_residual: 0 is perfect (tight fit), higher is worse (wasted space).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": if the post_residual is too small to fit typical items, 
    // it's often worse than opening a fresh bin.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: If the next item fits perfectly into this post_residual, reward it heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.8;
    }

    // 3. Adaptive Thresholding: If we are late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Base penalty is high to force filling existing bins.
        score += 65.0 - (progress * 20.0);
    }

    // 4. Distribution Balancing: If this bin's residual is significantly lower than the mean_residual,
    // it's a "tight" bin. We prefer to keep tight bins tight.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prefer tighter fits (Best Fit principle)
    // We want post_residual to be small, but not so small that it creates "dead space"
    // that cannot accommodate typical future items.
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is almost empty (if not the only choice)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item is large, favor bins that can still accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that have just enough space for the next item
            score -= 10.0;
        }
    }

    // Global state awareness:
    // If we have many open bins, we are incentivized to close them (fill them up).
    // If fitting_bins_count is 1, this bin is critical; prioritize filling it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Dynamic pressure: As we approach the end of the stream, prioritize 
    // packing density over flexibility.
    let density_factor = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= progress * 20.0 * density_factor;

    // Penalty for high mean_residual: if average space is high, avoid creating 
    // even more empty space.
    if mean_residual > 30.0 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let post = post_residual as f64;

    // Penalize creating "dead space" (small post_residual that cannot fit future items).
    // An ideal fit leaves 0 space, or enough space to potentially fit a future item.
    // We use a quadratic penalty for the "unusable" range (1..10).
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that have residuals close to the next_item_size to maintain high packing density.
    // If next_item_size is 0 (end of stream), we prioritize minimizing total residuals.
    let lookahead_alignment = if next_item_size > 0 {
        (post - next_item_size as f64).abs() * 0.5
    } else {
        post * 0.1
    };

    // Dynamic threshold: As the stream progresses, become more aggressive in packing
    // to avoid leaving too many bins partially filled.
    let progress_pressure = progress * (open_bins_count as f64) * 2.0;

    // Favor bins that already have low residuals to keep the bin "tight".
    let density_factor = (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Combine factors:
    // 1. Base cost is the remaining space (Best Fit principle).
    // 2. Add penalties for creating unusable small gaps.
    // 3. Subtract rewards for aligning with lookahead and current stream density.
    let mut score = post + dead_space_penalty + lookahead_alignment + progress_pressure - density_factor;

    // If this is a new bin (bin_residual == bin_capacity), increase its cost significantly 
    // unless no other bins fit or we are at the very end of the stream.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residuals (tight packing)
    // 2. Penalty for creating "dead space": if post_residual is in (0, 10), it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 3. Lookahead synergy: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Harmonic refinement: favor bins where the remaining space is minimal after the lookahead
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // 4. Thresholding for new bins:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if there are few open bins to choose from.
        if item_size > 70 || open_bins_count < 2 {
            score = 25.0;
        } else {
            score = 100.0; // Heavily penalize opening new bins for small items
        }
    }

    // 5. Global optimization: favor keeping the mean_residual high to avoid "bin fragmentation"
    // as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * 0.1) * progress;

    // 6. Harmonic class constraint: If this is the last fitting bin, prioritize it to keep the bin open.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

