    // If post_residual is in (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Best-Fit logic: prioritize bins that become very full
    // Lower post_residual is generally good, but penalize creating tiny shards.
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead: If the next item could fit into this post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Pressure: If we have many open bins, penalize opening a new one heavily.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If there are other bins that could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Global state: As we near the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual alignment: Penalize deviations from the mean to keep bin usage uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
