    if open_bins_count > 0 {
        let tightness_penalty = (post_residual as f64 - mean_residual).abs() * 0.5;
        score += tightness_penalty;
    }

    // New bin logic: only open a new bin if the current fit is extremely poor
    // OR if we are reaching the end of the stream and need to clear out lingering items
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can take it
            score += 85.0 + (progress * 20.0);
        } else {
            // Base cost for opening a new bin is the residual of a perfect fit
            score = 0.0;
        }
    }

    // Reward Best-Fit behavior by penalizing large post_residuals
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
