    }

    // 4. Tight fit preference: Favor bins that result in a smaller residual (Best Fit logic)
    // We adjust the score to make tighter fits more attractive
    score += (post_residual as f64) * 0.5;

    // 5. Progression scaling: As we reach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
