    // We add a quadratic penalty to discourage leaving large gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Strong reward for "perfect match" (post_residual == next_item_size)
        // Moderate reward for simply being able to accommodate the next item.
        let diff = (post_residual - next_item_size) as f64;
