    // If this is a new bin (bin_residual == bin_capacity), add a high base cost to discourage it
    // unless the open bins are truly suboptimal (high mean_residual).
    if bin_residual == bin_capacity {
        score += 65.0 + (mean_residual * 0.5);
    } else {
        // 4. Scarcity Penalty: If this is the only bin that can fit the item, 
        // prioritize it significantly to avoid wasting the opportunity.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 5. Mean Deviation: Discourage bins that are significantly "emptier" than the average.
        if (bin_residual as f64) > mean_residual {
