pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // We prioritize bins that leave the smallest residual (Best Fit),
    // but penalize opening new bins unless the fit is extremely poor or the lookahead suggests it.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin is high, but decreases as the stream progresses
        // to avoid "bottlenecking" late-stage items into tight, inefficient gaps.
        score += 45.0 * (1.0 - progress);

        // If we have very few open bins, opening a new one is cheaper.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    } else {
        // Reward filling bins tightly.
        // If this bin is the last one that can fit the item, prioritize it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Lookahead heuristic: If the next item is large and this bin can't fit it,
        // we might prefer a slightly worse current fit to keep this bin's residual large 
        // enough for future flexibility, or vice-versa.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Penalize "stranding" the next item: if this bin becomes useless for the next item,
                // we add a small penalty to keep options open.
                score += 5.0;
            }
        }

        // Encourage balancing the load across open bins.
        // If this bin's residual is significantly lower than the mean, it's a good candidate.
        if (post_residual as f64) < mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Penalize creating "dead space" (gaps smaller than the smallest likely incoming items).
    // Given the range (1..100), if post_residual is < 10, it's often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

