    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        // If the current placement leaves a gap too small for the next item, 
        // but the next item is large, penalize this choice.
        if post < next_f && post > 0.0 {
            score += (next_f - post) * 100.0;
        }
    }

    // Stability term: penalize deviation from the mean residual to encourage uniform filling
    let diff_from_mean = (post - mean_residual).abs();
    score += diff_from_mean * 20.0 * progress;

    // Favor bins that are already partially filled (lower bin_residual) as the stream progresses
    // to consolidate items in older bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 100.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

