    }

    // 4. Global state pressure: If we have many open bins, prioritize closing them.
    // Increase the penalty for creating a new bin if open_bins_count is already high.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Fragmentation control: Penalize creating "dead zones" (post_residual < 10).
    // Small residuals are often unusable for the given distribution (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Tight-fit priority: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 7. Dynamic balancing: As the stream nears completion, become more aggressive with packing.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit approach).
    // We want to minimize this, but we penalize bins that leave very small, unusable gaps.
    // A gap < 10 is often "dead space" because min item size is 10.
    let mut score = post_res;

    // Penalty for creating "micro-gaps" (1..9), which are harder to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, prefer bins that accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave a perfect fit for the next item.
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize filling existing bins 
    // over opening new ones to maximize bin density.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening new bins more heavily as we approach the end of the stream.
        score += 20.0 + (progress * 50.0);
    } else {
        // Reward existing bins that are close to the mean residual to keep distribution uniform.
        let residual_diff = (post_res - mean_residual).abs();
        score -= residual_diff * 0.2;
    }

    // If this is the last chance for this item, reduce penalty to ensure it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
