pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We add a non-linear penalty for creating "fragmented" space (small post_residual).
    // A post_residual between 1 and 9 is often "dead space" that cannot fit future items.
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large, we want to preserve larger residuals.
    // If next_item_size is small, we are less sensitive to tight fits.
    let lookahead_pressure = if next_item_size > 0 {
        let fit_diff = (post - next_item_size as f64).abs();
        if post < next_item_size as f64 { 50.0 } else { fit_diff * 0.5 }
    } else {
        0.0
    };

    // Global state coupling: As the stream progresses, favor packing tighter to minimize open_bins_count.
    // We penalize the "New Bin" (bin_residual == bin_capacity) increasingly as we near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
