    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that keep capacity for the next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 20.0; // Penalize bins that block the next item
        }
    }

    // Dynamic threshold for opening new bins:
    // As the stream progresses, become more conservative about opening new bins
    if is_new_bin {
        let open_penalty = 35.0 + (progress * 25.0);

        // Only consider a new bin if the mean residual is already quite tight
        if mean_residual < 15.0 {
            score += open_penalty * 0.5;
        } else {
            score += open_penalty;
        }

        // If this is the only bin that can fit the item, we must prioritize it
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Encourage filling bins that are already "half-empty" to consolidate space
        let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= utilization * 10.0;
    }

    // Adjust for global state: if many bins are open, penalize opening more
    score += (open_bins_count as f64).sqrt() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow flexibility as the stream ends
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 45.0 + 15.0
    } else {
        0.0
    };

    // Calculate normalized residual metrics
    let post_res_f = post_residual as f64;
    let mean_res_f = mean_residual;

    // Non-linear coupling: Favor bins that keep residuals close to the global mean,
    // but penalize small, unusable gaps (the "Best-Fit" logic combined with "Mean-Fill")
    let fit_efficiency = (post_res_f - mean_res_f).powi(2) * 0.1;

    // Incorporate lookahead: If next_item_size is large, favor bins with larger post_residual
    // to accommodate the future item, weighted by how many bins are available to help
    let lookahead_penalty = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post_res_f < needed {
            (needed - post_res_f) * (1.0 / (fitting_bins_count as f64 + 1.0))
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Combine factors
    // Lower score = higher priority
    let mut score = post_res_f + fit_efficiency + new_bin_penalty + lookahead_penalty;

    // Apply a slight pressure to consolidate items in fewer bins as we reach the end of the stream
    if progress > 0.8 && !is_new_bin {
        score -= (bin_capacity as f64 - post_res_f) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We favor bins that result in smaller residuals (tighter packing).

    // 2. Harmonic Class Logic:
    // If post_residual is small, we create "dead space". We penalize post_residuals 
    // that are too small to fit common item sizes (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 3. Lookahead Sensitivity (Next Item):
    // If the next item is large, we prefer to leave space for it.
    // If post_residual < next_item_size, we penalize because the current bin 
    // won't be able to accommodate the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that have the "perfect" size for the next item
            if post_residual >= next_item_size && post_residual < (next_item_size + 5) {
                score -= 10.0;
            }
        }
    }

    // 4. New Bin Threshold:
    // When bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if fitting_bins_count is low or if current bins 
    // are highly fragmented (mean_residual is high).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Penalize opening a new bin if we have many fitting options
            score += 40.0 + (fitting_bins_count as f64 * 5.0);
        }
    }

    // 5. Global Density Balancing:
    // If the current bin's residual is significantly above the mean, it's a "bad" bin.
    // We penalize placing items in bins that deviate negatively from the mean.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
