    // 6. Mean residual awareness: Penalize bins that are significantly emptier than the average,
    // which helps in keeping the "fullness" of bins balanced.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
