        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins that stay close to the current average 
    // to keep the packing density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Progression Weighting: As the stream nears completion, prioritize finishing off 
    // open bins (minimizing residuals) over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that result in smaller post_residual values.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // Ideally, we want post_residual to be exactly next_item_size to fill the bin perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for a perfect or near-perfect future fit
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 1.5;
        } else {
            // Penalize if the current placement makes the next item impossible to fit here
            score += 20.0;
        }
    }

    // 3. Fragmentation Control: Penalize creating "unusable" space (e.g., < 10)
    // if the average residual of other bins suggests we are already fragmenting.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; 
    }

    // 4. Global Density Balance: Compare this bin's post_residual to the global mean.
    // If this bin's residual is significantly lower than the mean, it's a high-quality bin.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are considering opening a new bin.
    // We only want to open a new bin if the fitting bins are all "bad" (e.g., leaving large gaps).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 80.0;
        } else {
            // Forced to open a new bin
            score = 0.0;
        }
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
