    // New bin handling: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless
    // the alternative (fitting_bins_count == 0) is forced, or we have too many open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Forced to open a new bin
        }
    } else {
        // Reward filling bins that are already partially filled to keep open_bins_count low
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
