    // (e.g., 50%, 75%, 90% utilization) to leave "clean" remainders.
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if utilization > 0.85 {
        score -= 20.0;
    }

    // 4. Scarcity adjustment: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Penalty: Make opening a new bin expensive unless the fit is 
    // exceptionally poor elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0; 
        // Penalize opening a new bin if we have many empty/near-empty bins already
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    // prioritize tighter packing to minimize trailing leftovers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

