    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 2.0;
    }

    // Dynamic adaptation: As the stream progresses, favor packing tighter 
    // to avoid opening new bins late in the sequence.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // based on how many open bins already exist. Only open a new bin if 
