    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item leaves very little space (ideal packing)
        score -= (100.0 - fit_diff) * 0.5;
    }

    // 3. Penalty for "Dead Space": If post_residual is small but > 0, it's often wasted.
    // However, if post_residual is 0, it's perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalize creating tiny slivers
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless
    // we are forced (fitting_bins_count == 0) or the current state is very inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If we MUST open a new bin, normalize the cost
            score = 50.0;
        }
    }

    // 5. Global Efficiency Adjustment:
    // As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // Already in 'score', but we penalize large gaps to avoid "swiss cheese" bins.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reduce the score.
    // This promotes packing pairs that complement each other perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decays as the stream progresses. We only open a new bin if the
    // existing options are truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score += 85.0 * (1.0 - progress * 0.5);

        // If we have many open bins already, make opening a new one more expensive
        // to encourage consolidating items into existing bins.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // 4. Fitting Constraint: If this is the only bin that fits the item (fitting_bins_count == 1),
        // provide a strong incentive to use it to avoid forced new bin allocation.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 5. Global Efficiency:
    // If the post_residual is below a "critical" threshold (e.g., < 15), 
    // it's likely a high-quality packing.
    if post_residual < 15 {
        score -= 20.0;
    }

    // 6. Mean Residual Balancing:
    // Penalize placements that push the bin's residual significantly away from the global mean.
    // This keeps the "tightness" of bins somewhat consistent.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    // We penalize high post-residual quadratically to avoid leaving large gaps
    let mut score = post * post / cap;

    // Lookahead logic: if next_item_size is large, we want to preserve bins with higher residuals
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post) * (1.0 - progress);
        if post < next_item_size as f64 {
            score += lookahead_penalty.powf(1.5);
        }
    }

    // Adaptivity: As the stream nears the end (progress -> 1.0), 
    // become more aggressive in filling bins to minimize new bin openings.
    let exhaustion_factor = 1.0 - progress;

    // Penalty for opening a new bin when existing options exist
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 10.0) * (1.0 + exhaustion_factor);
    }

    // Smoothing: Penalize residuals that deviate significantly from the mean_residual
    // This encourages uniformity in bin utilization (balancing)
    let deviation = (post - mean_residual).abs();
    score += deviation * exhaustion_factor;

    // Critical constraint: If this is the last fitting bin, prioritize it heavily
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
