    }

    // 3. Lookahead coupling: If the next item is large, favor bins that leave enough space for it.
    // If post_residual is less than next_item_size, we penalize the bin slightly to keep it for smaller items.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
