    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += mean_residual * 0.5;
    }

    // 6. Avoid fragmented bins: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 7. Penalty for creating "orphan" bins: 
    // If the current bin is empty and we have many open bins, penalizing new bin creation.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

