    // Encourage filling bins that already have low residuals (Best Fit behavior).
    // Penalize bins that are "too empty" compared to the mean.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // If this is the only bin that fits, prioritize it heavily to avoid a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
