    // As we approach the end of the stream, prioritize closing bins (minimizing residuals).
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    } else {
        // Early in the stream, favor keeping residuals closer to the mean to maintain flexibility.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "fragmented" space (small residues that are hard to fill).
    // The ideal post_residual is 0 (perfect fit). 
    // We use a quadratic penalty for small residuals to avoid "near-miss" waste,
    // but scale it by progress so the strategy becomes more aggressive late-game.
    let fragmentation_penalty = (100.0 - post_res).powf(1.5) * (1.0 + progress);

    // Lookahead logic: if the next item is large, favor bins that leave enough space
    // for it. If next_item_size is 0, we are at the end, so prioritize filling current bins.
    let lookahead_alignment = if next_item_size > 0 {
        if post_res >= next_item_size as f64 {
            -post_res * 0.5 // Reward bins that can accommodate the next item
        } else {
            post_res * 2.0 // Penalize bins that block the next item
        }
    } else {
        post_res * 0.1
    };

    // Global state awareness: 
    // If we have many open bins, penalize opening a new one (high residual).
    // If we have few open bins, we can afford a slightly worse fit to keep the count low.
    let bin_efficiency = (open_bins_count as f64) * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost
    // that increases as we get closer to the end of the stream to force consolidation.
    let new_bin_cost = if bin_residual == bin_capacity {
        50.0 + (progress * 150.0)
    } else {
        0.0
    };

    let score = fragmentation_penalty + lookahead_alignment + bin_efficiency + new_bin_cost;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
