    // If we have a next item, try to leave exactly enough room for it.
    // If post_residual is close to next_item_size, we reward this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= (50.0 / (1.0 + diff));
    }

    // 3. Prevent opening a new bin prematurely
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless we have no other choice (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Prefer empty bin over overflow
        }
    }

    // 4. Balance bin usage:
    // If the post_residual is significantly higher than the current mean_residual,
    // we are making this bin "less full" than others, which is generally bad.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency factor:
    // As we reach the end of the stream, prioritize closing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight (standard Best-Fit logic)
    // 2. Lookahead Integration: If next_item_size fits in this post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 3. Global Density Awareness: If we are late in the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Fragmentation Avoidance: If this is the last fitting bin, penalize high residuals 
    // to force a tighter fit elsewhere if possible, but don't penalize too hard to avoid new bins.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    // 5. New Bin Logic: Only open a new bin if the residual of current bins is very poor
    // or if the item is large and fits poorly in existing gaps.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Threshold for opening a new bin: only if existing bins are mostly full
            // or if the current item doesn't fit well in the mean gap.
            score = 60.0 + (mean_residual * 0.5);
        }
    } else {
        // Penalty for creating "dead zones" (residual too small for most items)
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We scale the penalty based on how many items are left. 
    // Early in the stream, we are more conservative (higher penalty for new bins).
    if is_new_bin {
        score += 15.0 + (35.0 * (1.0 - progress));
    } else {
        // If it's an existing bin, penalize if it leaves a "sliver" (fragmentation)
        // A post_residual between 1 and 9 is often unusable (dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
        }

        // Reward bins that bring the residual closer to the mean_residual of existing bins
        // This encourages "leveling" the fill across all bins
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * residual_diff;
    }

    // Lookahead logic: 
    // If the next item is large and won't fit in this post_residual, 
    // penalize this bin slightly to keep space open for the next item.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 30 {
        score += 12.0 * (next_item_size as f64 / 100.0);
    }

    // If this is the last fitting bin, prioritize using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best-Fit Decreasing logic with lookahead penalty)
    // post_residual: 0 is perfect, higher is wasted space.
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space that cannot fit common items.
    // If post_residual is small but not zero, it's often dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes (e.g., 20, 25, 33).
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 0.5;
    }

    // 3. Lookahead Logic: If a future item exists, prioritize bins that 
    // can accommodate the next item after the current one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Cannot fit next item, penalize significantly
            score += 40.0;
        } else {
            // Can fit next item, reward
            score -= 15.0;
        }
    }

    // 4. Thresholding: If this is the last fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Global state normalization: Penalize opening new bins 
    // if we have many bins already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage new bin if progress is late in the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly
    // from the average to maintain uniform packing density.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
