    // Targets "Perfect Fit" windows while penalizing fragments that prevent future packings.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Harmonic Penalty: Penalize residuals that are too small to fit common items (10-30)
    // but large enough to waste space.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // 2. Lookahead Synergy: If next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Fragmentation Control: Penalize creation of new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavily penalize opening new bin if others exist
        } else {
            score -= 50.0; // Reward opening new bin if it's the only option
        }
    }

    // 4. Density Balancing: If the bin is becoming highly fragmented compared to the mean,
    // penalize further placements to encourage filling "cleaner" bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // 5. Progress weighting: As the stream nears the end, prioritize tightest fits (Best Fit).
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small gaps that are likely unusable (1..9).
    // These gaps are "orphaned" because the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active,
    // but reward using an existing bin if it results in a very tight fit (Best Fit).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin
        score += 60.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to reduce fragmentation
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // provide a massive bonus to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Mean Residual Alignment: Penalize deviating from the average residual 
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small to fit typical items).
    // If post_residual is > 0 and < 10 (the minimum item size), it is highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the current post_residual,
    // we heavily reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Prevent opening a new bin prematurely.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large
        // and doesn't fit well elsewhere.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Balance current bin with the global mean.
    // We want to keep bins filled similarly to the mean to avoid extreme outliers.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Urgency: If this is the last chance to fit the item (fitting_bins_count == 1),
    // we make this bin very attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Scale by progress: Towards the end of the stream, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
