    // 1. Best Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // The base score is already post_residual, which naturally implements Best Fit.

    // 2. Lookahead Penalty: If a future item fits perfectly in this bin's post_residual, 
    // it is highly desirable to keep that space.
    if next_item_size > 0 {
        if (post_residual as i32 - next_item_size as i32).abs() < 5 {
            score -= 20.0;
        } else if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the fit is truly terrible.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy penalty that
    // scales with how many existing bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 15.0) + (progress * 20.0);
    }

    // 4. Global State Awareness: If we are nearing the end of the stream, 
    // tighten the requirements for opening new bins.
    if progress > 0.8 {
        score += (1.0 - progress) * 50.0;
    }

    // 5. Fragmentation Avoidance: Penalize leaving small, unusable gaps (1-9) 
    // unless it's the only option.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 6. Mean Residual Balancing: If the current bin is "emptier" than the average, 
    // prioritize filling it to keep the average occupancy high.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize empty bin opening as the stream progresses to encourage densification
    let new_bin_penalty = 15.0 * (1.0 + progress);
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller post_residuals (Best Fit)
    // Add non-linear term to penalize bins that leave very small, unusable gaps (1-9)
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Incorporate lookahead: if next_item fits in current post_residual, reduce score (reward)
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -12.0 * (1.0 - (post_res / 100.0))
    } else {
        0.0
    };

    // Weight the mean residual to maintain balance across open bins
    // If this bin is much tighter than the mean, prioritize it
    let balance_factor = 2.0 * (post_res - mean_residual);

    let mut score = post_res + gap_penalty + lookahead_reward + balance_factor;

    if is_new_bin {
        score += new_bin_penalty;
    } else {
        // If it's the last fitting bin, slightly lower the score to prevent premature new bin opening
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
