    let post = post_residual as f64;

    // Base score is the post-residual space (Best Fit strategy)
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..10 range is generally useless)
    // We penalize post_residuals that are small but not zero.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If next_item_size is large, favor larger post_residuals
    // to accommodate future items, scaled by progress to be more cautious as the stream ends.
    if next_item_size > 0 {
        let lookahead_fit_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * (1.0 + progress)
        } else {
            0.0
        };
        score += lookahead_fit_penalty;
    }

    // New bin logic:
    // If this is an empty bin (bin_residual == bin_capacity), apply a heavy threshold penalty
    // that decreases as the stream progresses (making it easier to open bins late-game).
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress * 0.5);
    }

    // Global optimization: If this is the only bin that fits the item, reward it significantly
    // to prevent unnecessary overflow into a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Normalize by open_bins_count to favor consolidating items into existing bins
    // rather than spreading them across many active bins.
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals to prioritize tight packing.
    // We use exponential growth to make "near-perfect" fits (residual < 5) extremely attractive.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Lookahead: If next_item_size is known, try to leave space for it.
    // If post_residual is slightly less than next_item_size, it's a "bad" fit because it orphans space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding space that can't fit the next item
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward: we can fit the next item perfectly
            score -= (next_item_size as f64) * 1.2;
        }
    }

    // 3. Prevent fragmentation: If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Threshold: If we are forced to open a new bin, make it expensive unless the current 
    // average residual is already very high (meaning we are wasting space anyway).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 5. Harmonic Class dampening: Penalize bins that are "half-full" (the hardest to fill later).
    // Bins with residual ~50 are often problematic in 1D bin packing.
    let residual_dist_from_mid = (post_residual as f64 - 50.0).abs();
    score += (50.0 - residual_dist_from_mid) * 0.2;

    // 6. Global progression: As we approach the end of the stream, prioritize closing bins over efficiency.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // If post_residual is in the range (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the 
    // current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 40.0;
        } else if gap_after_next < 10 {
            score += 20.0; // Penalty for leaving a tiny, unusable sliver
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // We heavily penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // proportional to the number of bins already open.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Density: If this is the only bin that fits, prioritize it strongly
    // to avoid premature new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Balance: Adjust based on how full the bin is relative to the mean.
    // We prefer to keep bins balanced to keep options open for future items.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (fill_ratio - mean_residual / bin_capacity as f64).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large gaps (standard Best-Fit logic)
    // We already start with post_residual, which heavily favors smaller gaps.

    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward it.
    // This creates a "Best-Fit-with-Lookahead" behavior.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0; // Significant incentive for creating a bin that fits the next item perfectly

        // Refine: reward bins that leave minimal space after placing BOTH current and next item
        let double_post = post_residual - next_item_size;
        score -= (100.0 - double_post as f64) * 0.1;
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless existing options are poor.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual is already quite low (bins are full),
            // or if we have very few options to fit the current item well.
            score += 35.0; 
            if mean_residual < 20.0 {
                score -= 10.0;
            }
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits, prioritize it heavily to avoid wasting space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to keep bins tight.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
    // significantly reward this placement (lower the score).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Penalty for starting new bins: only open a new bin if the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 35.0; 
        // Dampen new bin penalty as we approach the end of the stream 
        // to avoid leaving too many bins half-empty.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 15.0;
    }

    // 4. Global state awareness: if we have many bins open, prioritize filling existing ones.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Avoid "fragmentation traps": if only one bin fits, prioritize it unless it leaves a 
    // tiny, unusable sliver (e.g., 1-9 units).
    if fitting_bins_count == 1 && post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // 6. Dynamic balance: favor bins whose current state is close to the global mean,
    // reducing variance in bin packing density.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating 'dead space' that is too small for common item sizes
    // We penalize small residuals that are unlikely to accommodate the next item
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powf(1.5);
    }

    // Lookahead logic: if next item doesn't fit in the current post_residual,
    // we penalize the bin slightly to encourage saving it for a better match.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 5.0 * (1.0 - progress);
    }

    // Dynamic threshold: As the stream progresses, we become more conservative about 
    // opening new bins. If this is a new bin (res == cap), penalize it based on 
    // the current mean_residual to prevent fragmentation.
    if res == cap {
        score += mean_residual * 0.5;
        // Increase penalty for opening new bins as the stream nears completion
        score += progress * 40.0;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && res < cap {
        score -= 10.0;
    }

    // Reward bins that have residuals closer to the average to maintain bin density
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to encourage tight packs.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of common item sizes (20, 25, 33).
    // This creates "bins of specific types" (e.g., bins that prefer 20s or 25s).
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 2.0;
    }

    // 3. Lookahead Integration: If the next item fits into the current post_residual, drastically reduce score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
    }

    // 4. Thresholding: Avoid creating "dead zones" (residuals < 10 are often unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Global state normalization: Penalize opening new bins when many bins are already open,
    // but favor opening a new bin if the current mean_residual is very high (indicating poor packing).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        score += (open_bins_count as f64) * 2.0;
        if mean_residual > 30.0 {
            score -= 15.0;
        }
    } else {
        // This is an existing bin.
        score -= (fitting_bins_count as f64) * 2.0;
    }

    // 6. Progressive tightening: As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "sliver" gaps (dead space < 10)
    // and use open_bins_count to modulate the aggressiveness of opening new bins.

    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable gap between 1 and 9).
    // If post_residual is in (0, 10), it is very likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // If this is a new bin, penalize based on current bin pressure.
    // If we have many bins open already, opening a new one is expensive.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we have very few open bins, opening a new one is cheaper.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    } else {
        // For existing bins, reward fits that leave the bin closer to the mean residual of other bins.
        // This promotes uniform packing density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Lookahead logic: If the next item is large and this bin can't fit it, 
    // try to keep the residual high enough to fit potentially large future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Final constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE #623: Aggressive 2-step lookahead matching.
    // Minimizes the post-fit residual while penalizing placements that isolate 
    // small, unusable fragments (dead space) relative to the next anticipated item.

    let mut score = post_residual as f64;

    // 1. Reward tight fits that leave exactly 0 space (Perfect fit).
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Penalty for creating "dead space": If the remaining space is too small 
    // to fit the next item, penalize it heavily.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Reward placements that bring the bin residual closer to the global mean 
    // to maintain uniformity across bins (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Strategic New Bin Threshold:
    // If this is an empty bin (new bin candidate), only choose it if the current
    // fitting options are extremely poor (i.e., they would all result in high post_residuals).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the current state is forced.
        score += 40.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // If it's the last chance (fitting_bins_count == 1), reward taking the fit 
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Lookahead optimization: If post_residual is a near-perfect match for the 
    // next item, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 30.0; // Strong incentive for 2-step packing
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (the "Best-Fit" logic).
    // We want to minimize wasted space, but specifically avoid creating "slivers" (very small residuals).
    // A post_residual < 10 is often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead Integration: If the next item can fit perfectly into the current post_residual,
    // strongly incentivize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward perfect fit (diff == 0) more than near-fits
        score -= 25.0 * (1.0 / (1.0 + diff));
    }

    // 3. Global State: If we are near the end of the stream, prioritize filling existing bins
    // to avoid leaving half-empty bins at the finish.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate), 
    // penalize opening it unless the fit quality in other bins is poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the average
        // residual is high, indicating we are wasting space across the board.
        score += 20.0 + (open_bins_count as f64 * 0.5);
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // 5. Fitting Constraint: If this is the ONLY bin that can fit the item, 
    // reward it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // We aim to minimize the residual space (Best Fit), but penalize small gaps that are hard to fill.
    // A gap of 1-9 is often "dead space" because min item size is 1.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we penalize this placement to keep larger gaps open.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_residual as f64) * 0.5
    } else {
        0.0
    };

    // Dynamic threshold: As we approach the end of the stream, be more aggressive with packing (lower score).
    // Earlier in the stream, favor keeping bins with higher mean_residual open.
    let efficiency_bias = (mean_residual - post_res) * (1.0 - progress);

    // If bin_residual == bin_capacity, we are evaluating opening a NEW bin.
    // We only want to open a new bin if the current options are very poor.
    let base_score = if bin_residual == bin_capacity {
        // High cost to open a new bin, decreases as the stream progresses and packing density drops.
        45.0 + (progress * 10.0)
    } else {
        post_res
    };

    base_score + gap_penalty + lookahead_penalty + efficiency_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but unusable (1-9 range)
    // as they likely create 'orphaned' space that cannot fit subsequent items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // significantly lower the score to encourage "perfect pairing".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: If this is a new bin (residual == capacity),
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        score = 45.0;
        // Reduce penalty if we are running out of open bins or if fitting bins are crowded.
        if open_bins_count > 5 {
            score += 10.0;
        }
    } else {
        // 4. Density Balancing: Prefer bins closer to the mean_residual to keep 
        // usage uniform across the bin pool.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid 
    // creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
