pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // We want to minimize the post_residual, so it is already the base score.

    // 2. Lookahead Synergy: If the next item fits perfectly into this post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward perfect fit or near-perfect fit
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean_residual is already quite tight
        // and we have very few fitting options.
        if fitting_bins_count > 0 && mean_residual > 20.0 {
            score += 45.0; 
        } else {
            score += 25.0;
        }
    }

    // 4. Mean Residual alignment: avoid creating outliers.
    // If the post_residual is significantly higher than the current mean, 
    // it suggests this bin is becoming an "empty" bin, which is inefficient.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize space consolidation
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // In the final phase, be extremely aggressive about filling gaps
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing variant with lookahead awareness)
    // post_residual: smaller is better (Best Fit)
    // penalty for opening new bins when current bins could accommodate

    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    if is_new_bin {
        // Only consider a new bin if we have few options or if current open bins are inefficient
        // Penalize new bin creation based on current bin occupancy
        score += 45.0 + (open_bins_count as f64 * 2.5);

        // If we are near the end of the stream, penalize new bins heavily to encourage packing
        score += (1.0 - progress) * 20.0;
    } else {
        // Reward bins that leave space for the next item (Lookahead optimization)
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Strong reward for accommodating lookahead
            } else if post_residual > 0 && post_residual < 15 {
                score += 20.0; // Penalize creating "dead space" that fits nothing
            }
        }

        // Favor bins that maintain a high mean_residual (keep bins balanced)
        // Adjust score based on deviation from the mean
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // If this is the last fitting bin, slightly reward placing here to avoid opening a new bin later
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than 0. We penalize small residues that can't fit typical items.
    if post > 0.0 && post < 15.0 {
        score += 20.0 * (1.0 - (post / 15.0));
    }

    // Lookahead logic: if next item is large, favor keeping bins open that have more space.
    // If next_item_size is large, we want to prioritize bins with high post_residual.
    if next_item_size > 50 {
        score -= post * 0.5;
    }

    // Progression coupling: As the stream nears the end, become more aggressive 
    // about filling bins tightly to avoid trailing bins.
    score += (progress * 10.0) * (post / bin_capacity as f64);

    // If this is the only fitting bin, reduce its score to prioritize closing it 
    // rather than opening a new bin, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the number of open bins and the mean residual.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5) + (mean_residual * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it naturally acts as a Best-Fit base.

    // 2. Harmonic Class Logic: Reward placements that leave remainders 
    // that are multiples of common item sizes or "tight" thresholds.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // 3. Lookahead Synergy: If the next item is large, avoid leaving a residual 
    // that is slightly smaller than the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for "dead space" that cannot fit the next expected item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward "perfect fit" potential for the next item
            score -= (100.0 / (1.0 + (post_residual - next_item_size) as f64)) * 2.0;
        }
    }

    // 4. Bin Conservation: If this is the only bin that fits the item, 
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the fit is truly poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very low
        // or if we have very few open bins (early game strategy).
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // 6. Density balancing: Penalize creating many bins with high residuals.
    if open_bins_count > 0 {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small, unusable residues (1..9)
    // which are likely to remain empty for the rest of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // reward this placement to keep the bin tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin (bin_residual == bin_capacity)
    // unless the current open bins are already very full (low mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward filling bins that have low residual space (Best Fit intuition)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity Constraint: If this is the last bin that can fit the item,
    // lower the score to force usage of existing capacity before spawning a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We weight this by the number of bins already open to discourage fragmentation.
    score += (post_residual as f64) * (1.0 + (open_bins_count as f64 / 10.0));

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // heavily reward this bin selection to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough space for the next item
            score -= (100.0 - (post_residual - next_item_size) as f64).min(50.0);
        }
    }

    // 3. Fragmentation Avoidance: If the post_residual is small (e.g., < 10), it is likely 
    // "unusable" space. Penalize these "sliver" bins unless they are the only option.
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }

    // 4. Mean-Residual Balancing: If this bin's post_residual is significantly better 
    // than the average residual, promote it.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // 5. New Bin Logic: If this is a new bin (bin_residual == capacity), 
    // only choose it if it's the absolute last resort (high penalty).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, reduced as open_bins_count increases
        // to balance against the cost of extreme fragmentation.
        score += 200.0 - (open_bins_count as f64 * 2.0);
    }

    // 6. Last Chance Reward: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // Logic:
    // 1. Base score is post_residual. Minimizing this is Best-Fit.
    // 2. Penalize opening new bins unless the current bin state is extremely poor.
    // 3. Use next_item_size lookahead to avoid creating "orphaned" residuals that cannot fit future items.
    // 4. Use mean_residual to balance the bin landscape.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only open if the current fit is terrible.
    if is_new_bin {
        // Only open new if we have many bins already or if the average space wasted is already high.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward fitting into bins that are already tight (Best Fit logic).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Lookahead: penalize residuals that are too small to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates a "dead" zone for the next item.
            score += 30.0;
        } else {
            // This placement leaves room for the next item.
            score -= 15.0;
        }
    }

    // Global state adjustment: if we have many open bins, prioritize clearing them.
    if open_bins_count > 5 {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Progression: As we approach the end of the stream, be more conservative with opening bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base Best-Fit objective: minimize post_residual.
    // We add a penalty for "fragmentation" (small post_residual that is hard to fill).
    // If post_residual is < 10 (the min item size), it is essentially dead space.
    let fragmentation_penalty = if post_residual < 10 && post_residual > 0 { 25.0 } else { 0.0 };

    // Lookahead logic: If next_item_size is large, favor bins that can accommodate it.
    // If next_item_size > post_residual, we penalize this bin for being too small for the future.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        (next_item_size as f64 - post as f64) * 0.5
    } else {
        0.0
    };

    // Global state awareness:
    // As the stream progresses, we become more conservative about opening new bins.
    // Penalize the "New Bin" candidate (bin_residual == capacity) more heavily as progress increases.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * progress) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Favor bins that align with the current mean_residual to keep bin distribution uniform.
    let variance_penalty = (post - mean_residual).abs() * 0.1;

    // Combine into a non-linear objective
    // We use post^1.5 to aggressively penalize large empty spaces while keeping small residuals attractive.
    let score = (post.powf(1.5)) 
        + fragmentation_penalty 
        + lookahead_penalty 
        + new_bin_penalty 
        + variance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but non-zero,
    // as they often create "dead space" that cannot fit future items.
    // We favor residuals that are either 0 or large enough for likely items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: If the next item is large, favor keeping larger
    // residuals open. If next_item_size is 0 (end of stream), prioritize filling
    // current bins to minimize total count.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
