    // 3. Density Balancing: If we have many open bins, penalize opening a new one 
    // unless the fit is perfect (Best Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        score += (open_bins_count as f64 * 2.0);
    }

    // 4. Harmonic Modulo Bias: Favor bins where the post_residual is a multiple
    // of common item sizes (e.g., 20, 25), increasing the probability of 
    // future perfect fits.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // become more aggressive in filling bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
