    // If post_residual is in the 1-9 range, it's very likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Best-Fit logic: prioritize bins where post_residual is small (already handled by base score),
    // but penalize opening a new bin if other bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin: proportional to how well the item could have fit elsewhere.
        score += 45.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 3. Lookahead heuristic: If the next item is large, favor keeping space open.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin will likely be unable to take the next item.
            score += 15.0;
        } else {
            // This bin can fit the next item; reward this (Best-Fit-Lookahead).
            score -= 20.0;
        }
    }

    // 4. Global state coupling: 
    // If many bins are open, push to fill them tighter.
    // If the current bin is significantly emptier than the average, use it to avoid fragmenting.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // 5. Progression adjustment: 
    // Towards the end of the stream, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

