        // and have a residual near the mean to keep bin usage density uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 6. Final safety: If this is the last chance for the current item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

