    // unless fitting_bins_count is zero.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Strong penalty to force reuse of existing bins
        }
    } else {
        // 5. Fragmentation Avoidance: If we are nearing the end of the stream, 
        // aggressively pack to close bins.
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 && post_residual < 15 {
            score -= 20.0; // Reward tight packing late in the stream
        }
    }

    // 6. Mean Residual Balancing: Avoid creating bins that are significantly 
    // more empty than the average, which wastes capacity.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small to fit any likely subsequent items
    // If post_residual is in the range (0, 10), it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

