    }

    // 4. Last Chance Heuristic: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid opening a new unnecessary bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

