            score += 10.0;
        }
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin.
        // Penalty increases as we approach the end of the stream to favor packing into existing bins.
        score += 40.0 + (progress * 50.0);
    } else {
        // Bias towards bins that keep the mean residual balanced.
        let deviation = (post_res - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

