    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // divisible by common item sizes or that fit the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "Perfect Fit" potential for the upcoming item
            score -= (bin_capacity - post_residual) as f64 * 0.8;
            score -= (next_item_size as f64) * 2.0;
        } else {
