        // or if we have very few open bins (avoiding fragmentation early).
        let progression = step_index as f64 / total_items as f64;
        score += mean_residual * 0.75;
        score += (open_bins_count as f64) * 5.0 * (1.0 - progression);
    } else {
        // 4. Fragmentation Avoidance:
        // If this is the last bin that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Penalize creating "impossible" tiny residues (< 10) that are unlikely to fit future items.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // 5. Harmonic alignment: 
    // Favor residuals that are multiples of 20 (common divisor of 100).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
