        let fit_next = (post_residual as i32 - next_item_size as i32) >= 0;
        if fit_next {
            // Reward bins that can accommodate the lookahead item
            score -= 15.0 * (1.0 - progress);
        } else {
            // Penalize bins that leave insufficient space for the lookahead
            score += 10.0 * progress;
        }
    }

    // Coupling: If fitting_bins_count is low, we are running out of options for this item.
    // Discourage opening new bins unless the current options are very poor (high post_residual).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Adjust for mean_residual: if current bin is significantly worse than the average bin,
    // penalize it to favor maintaining a uniform fill density across open bins.
    let residual_delta = (post_residual as f64) - mean_residual;
    score += residual_delta * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (sliver waste).
    // If post_residual is in the range [1, 9], it is likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // prioritize this bin heavily (Best-Fit-Lookahead logic).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward placements that leave exactly enough space for the next item.
        score -= 40.0 * (1.0 / (1.0 + diff));
    }

    // 3. Fragmentation Control: If this is the only fitting bin, resist opening a new one
    // unless the current fit is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Capacity Normalization: Favor bins that stay close to the global mean residual.
    // This maintains a balanced distribution of capacity usage across the open set.
    let residual_balance = (post_residual as f64 - mean_residual).abs();
    score += residual_balance * 0.5;

    // 5. New Bin Threshold: If evaluating a new bin (bin_residual == bin_capacity),
    // impose a high barrier to prevent premature bin opening.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Adjust barrier based on stream progress: later in the stream, be more conservative.
        score += (step_index as f64 / total_items as f64) * 15.0;
    }

    // 6. Modulo Harmonic Bias: Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
