        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary or highly efficient.
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Synergy: If the next item fits into the remaining post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it to avoid 
    // fragmenting the open bin set unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Efficiency: Penalize bins that deviate significantly from the mean residual
    // to keep the bin set "balanced" in terms of remaining capacity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progression scaling: As we reach the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (post_residual).
    // We prioritize keeping the post_residual as low as possible to pack tightly.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If post_residual can fit the next item, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        // High reward for creating a perfect or near-perfect fit for the next item.
        let fit_margin = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_margin) * 2.5;
    }

    // 3. Fragmentation Penalty: Penalize creating a bin that is too empty compared to the mean.
    // If the post_residual is significantly larger than the mean_residual, it is likely a poor bin.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 4. Open Bin Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // 5. New Bin Threshold: If evaluating a new bin (residual == capacity),
    // we set a baseline cost to encourage filling existing bins first.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin is dynamic based on how many bins are already open.
        // More open bins make opening another one slightly less expensive than 
        // forcing a terrible fit into an existing bin.
        score = 85.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // with packing to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (too much waste)
    // We favor bins where post_residual is small (tight fit)
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let waste_after_next = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 space for the next item
        score -= (100.0 - waste_after_next) * 1.5;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fits are extremely poor (large residuals) or we are nearing the end.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost + dynamic scaling
        // If fitting_bins_count is 0, we MUST open, so set score low.
        if fitting_bins_count == 0 {
            score = -1000.0; 
        } else {
            // Otherwise, make it expensive to open a new bin early on
            score += 45.0 + (progress * 20.0);
        }
    } else {
        // 4. Global State Balancing: If we have many open bins, prioritize 
        // filling the one that is already most full (Best Fit).
        // If mean_residual is large, we are spreading items too thin.
        if mean_residual > (bin_capacity as f64 * 0.4) {
            score -= (bin_capacity - bin_residual) as f64 * 0.2;
        }
    }

    // 5. Final constraint: Avoid creating 'dead zones' (space too small for any likely item)
    // If post_residual is < 10 (smallest possible item size), it's likely dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We add a penalty for "Dead Space" (small residuals that are hard to fill)
    // A residual < 10 is often unusable, so we penalize it exponentially.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        100.0 / (post_residual as f64 + 1.0)
    } else {
        0.0
    };

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we reward this placement to keep bins tightly packed.
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Avoid opening new bins too early by penalizing the "New Bin" candidate 
    // proportional to the current average waste and progress.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 + (mean_residual * 0.5)) * (1.0 - (progress * 0.2))
    } else {
        0.0
    };

    // Reward bins that have a residual close to the mean_residual of all bins,
    // encouraging uniform filling across the set.
    let uniformity_score = (post - mean_residual).abs() * 0.1;

    // Combine factors
    // Lower score is better.
    let mut score = post + dead_space_penalty + lookahead_reward + new_bin_penalty + uniformity_score;

    // If this is the last chance for this item (only one bin fits it), 
    // heavily incentivize taking that bin to prevent forced new-bin allocation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Small post_residuals are usually good (tight packing), 
    // but can create "dead fragments" < 10. Penalize fragments that are too small to fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes, or aligns with the next_item_size to minimize fragmentation.
    if next_item_size > 0 {
        // If the post_residual is a perfect fit for the next item, heavily reward it.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // If the post_residual can accommodate the next item with minimal waste.
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // If the next item cannot fit in this residual, penalize the waste.
            score += 15.0;
        }
    }

    // 3. Dynamic Thresholding: Adjust based on bin utilization.
    // As we progress, prefer tighter packing if we have many bins open.
    let utilization_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization_factor * 10.0;

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the current "best" fit is poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already and fitting_bins_count is low,
        // or if the current item is very large (e.g., > 70).
        if open_bins_count > 5 && item_size < 70 {
            score += 50.0; // Strongly discourage opening new bins unless necessary
        } else {
            score += 20.0; // Moderate neutral penalty
        }
    }

    // 5. Fitting constraint: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (too small for most items), 
    // it is highly undesirable. We penalize gaps in the (0, 10] range heavily.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
