    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Open Bins Pressure: Penalize opening a new bin if we have plenty of open bins,
    // but reward opening a new bin if we are forced to create "bad" fragments.
    if is_new_bin {
        // High cost to open a new bin if we have many bins already
        score += (open_bins_count as f64) * 5.0;

        // If it's the very last item, opening a new bin is always expensive
        if step_index == total_items - 1 {
            score += 100.0;
        }
    } else {
        // Encourage using existing bins that are already "open"
        score -= (open_bins_count as f64) * 0.1;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Aggressive 2-step lookahead matching (Archetype #773)
    // Objective: Minimize post_residual, but heavily penalize placements that
    // isolate small remainders that cannot fit the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins if there are existing fitting options
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            // Reward starting a new bin if nothing else fits well
            score -= 20.0;
        }
    }

    // 2. Lookahead matching: If post_residual is slightly too small for next_item_size,
    // it creates 'dead space'. Penalize remainders that are between 1 and next_item_size-1.
    if next_item_size > 0 && post_residual < next_item_size {
        if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
