    // 3. Efficiency alignment: Reward placements that bring the bin's residual
    // closer to the global mean_residual, discouraging outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. Tightness bias: Favor bins that are near-full (Best Fit property)
    // especially as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * 0.5 * progress;

    // 5. Final constraint: If this is the last chance for this bin (fitting_bins_count == 1),
    // and the resulting post_residual is very small (< 10), reward it to "clean up" the bin.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
