    // exactly enough space for it (or close to it) to minimize fragmentation.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score += diff * (1.0 + progress);
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly.
    if fitting_bins_count > 0 {
        // Penalty for opening a new bin when existing ones can fit the item.
        if bin_residual == bin_capacity {
            score += 150.0 * (1.0 - progress);
        }
    } else {
        // If this is a new bin, neutralize the penalty if no other options exist.
        if bin_residual == bin_capacity {
            score -= 50.0;
        }
    }

    // Global state optimization: penalize increasing the number of bins
    // proportional to the current bin count to encourage density.
    score += (open_bins_count as f64).sqrt() * 10.0;

    // Interaction term: penalize bins that deviate significantly from the mean residual
    // to keep the bin distribution uniform.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

