            score += 15.0;
        }
    }

    // 4. Harmonic capacity logic: Favor bins that leave a residual which is a multiple 
    //    of likely item sizes (e.g., 20, 25, 33).
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // 5. Progression awareness: As we approach the end of the stream, 
    //    prioritize packing density (lower residual) over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. New-bin thresholding: If this is an empty bin, only open it if 
    //    the current fit is extremely poor (fitting_bins_count logic).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if other bins are available
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
