    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 30.0 {
            score += 50.0; // High penalty to prevent opening new bins prematurely
        } else {
            score -= 5.0; // Allow opening if open bins are already very full
        }
    }

    // 5. Global pressure: as we approach the end of the stream, prioritize 
    // filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. If this is the only bin that can fit the item, prioritize it to avoid 
    // forcing a new bin opening unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
