        }
    }

    // Heuristic for New Bin (bin_residual == bin_capacity):
    // Only open a new bin if the current open bins are "too full" to accept
    // the current item efficiently, or if the item is large.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
