    let mut score = post;

    // Penalty for creating a 'sliver': residuals that are too small to fit typical future items (e.g., < 10)
    // We scale this penalty by the progress to be more aggressive towards the end of the stream
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if the next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post < next_item_size as f64 {
