    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced as we approach the end of the stream
        // to minimize final bin count.
        score += 40.0 * (1.0 - progress * 0.5);

        // If we have many open bins, penalizing new bin creation is more critical.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins that align with the mean residual to keep bin fullness consistent
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // heavily reward this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
