    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead zones" (residuals too small for common items)
    // Residuals < 10 are often problematic; strongly penalize them.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead synergy: if next item fits perfectly, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits for the next item
        score -= (30.0 - diff).clamp(0.0, 30.0);
    }

    // 3. Dynamic New-Bin Threshold
    // If we are early in the stream, favor filling existing bins. 
    // If we are late, be more aggressive about keeping bins "clean".
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // We only open a new bin if the average residual is already quite low (high fragmentation).
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 20.0;
        } else {
            score += 60.0 + (progress * 40.0);
        }
    } else {
        // 4. Prefer bins that are already "semi-full" to keep open_bins_count low
        // Penalize placing in very empty bins if others are available
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;

        // 5. If this is the only bin that fits the item, make it highly attractive
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
