    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for common items.
    // As the stream progresses, we become more conservative about wasting space.
    let dead_space_penalty = if post_residual < 10 {
        (10.0 - post_residual as f64) * (1.0 + progress * 2.0)
    } else {
        0.0
    };
    score += dead_space_penalty;

    // Lookahead: if the next item is large, prioritize keeping space open.
    // If post_residual is slightly larger than next_item_size, it's a good fit.
    if next_item_size > 0 {
