            }
        } else {
            // Penalize creating a bin that cannot take the next item if we have other options
            score += 10.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global mean to 
    // keep bin utilization uniform (prevents "fragmentation" of bin states).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
