    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.2;

    // 5. Progression Scaling: As we reach the end of the stream, be more aggressive
    // about fitting into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
