        score += 20.0;
    }

    // 4. Global state awareness: If this is the only fitting bin, 
    // heavily reward it to avoid opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New bin management: If evaluating a new bin (bin_residual == bin_capacity),
    // add a base cost to open a new bin, making it less attractive than filling existing ones.
    if bin_residual == bin_capacity {
        score += 35.0;

        // As the stream progresses, increase the cost of opening new bins
        // to encourage consolidation.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Mean residual balancing: If post_residual is significantly worse than
    // the global average, add a penalty to encourage uniform bin usage.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want the smallest post_residual (Best Fit), but we penalize fragmentation.
    // A post_residual of 0 is perfect, so we use it as the anchor.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the best existing bin leaves a "dead zone" (e.g., < 10)
    // that cannot accommodate the next item or future expected items.
    if is_new_bin {
        if fitting_bins_count == 0 {
