        if next_item_size > 0 && post_residual < next_item_size {
            // This placement creates a "dead zone" for the next item.
            // If we have other bins that could take the next item, this is bad.
            score += 150.0 * (1.0 - progress);
        }

        // Favor placements that bring the bin residual closer to the global mean residual
        // to keep bin utilization balanced.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;

        // Final threshold: If this is the last chance to fit the item in an existing bin,
        // reduce the penalty to encourage consolidation.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
