    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the (0, 10) range specifically as they are unusable.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the next item compact.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic adaptation: As the stream progresses, favor packing tighter (lower residual).
    // This discourages opening new bins late in the stream.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales up as we approach the end of the stream.
        // We add a term that increases the cost of starting a new bin based on progress.
        score += 25.0 + (progress * 50.0);
    } else {
        // If it's an existing bin, favor it more if the mean residual is high,
        // to consolidate space usage.
        score -= (mean_residual - post) * 0.2;
    }

    // If this is the last fitting bin, prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Non-linear coupling: penalize high post_residual disproportionately as the 
    // stream reaches its end to force tighter packing.
    score += (post * post) / (bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
