        // If we have many open bins, penalize starting a new one
        score += open_bins_count as f64 * 2.0;
        // If the mean residual is already high, we shouldn't open a new bin
        score += mean_residual * 0.5;
    }

    // 6. Progressive scaling:
    // As the stream progresses, prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

