    let sliver_penalty = if post > 0.0 && post < 10.0 {
        15.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Use lookahead: if next_item_size can fit into this post_residual, 
    // reward this bin to keep it "active" for the next step.
    let lookahead_bonus = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -12.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Interaction term: Prefer bins that stay close to the current mean_residual 
    // to maintain a uniform distribution of usage across bins.
    let variance_penalty = (post - mean_residual).abs() * 0.1;

    base_penalty + post + sliver_penalty + lookahead_bonus + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // However, we penalize "near-empty" remaining space that is too small for common items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalize creating "slivers" that are hard to fill
    }

    // 2. Lookahead utility: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for keeping space for the next item
        } else {
            score += 5.0; // Minor penalty for stranding the next item
        }
    }

    // 3. Harmonic class management:
    // If the bin is new, only pick it if current bins are very full (high mean_residual is bad)
    // or if we have no good fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Force new bin if nothing else fits
        } else {
            // Otherwise, heavily discourage opening a new bin
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 4. Density awareness:
    // If we are nearing the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0; 
    }

    // 5. Modulo-based "perfect fit" incentive:
    // If we fill the bin exactly, apply a massive bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residuals that are too small to fit common items
    // but large enough to waste capacity. If post_residual is in (0, 10), it's a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead: If the next item exists, penalize bins that can't fit it after this placement
    if next_item_size > 0 && post_residual < next_item_size {
