        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward using existing bins to keep count low
        score -= (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting constraints: If this is the last chance for this item, reduce penalty
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean residual balancing: Penalize deviating significantly from the average bin fill
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
