    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items (below 15).
    // The penalty is modulated by progress to be more aggressive in the late game.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * (1.0 + progress * 2.0);
    }

    // Reward bins that can accommodate the lookahead item.
    // If the next item fits into the current post_residual, we favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 * 0.85);
    }

    // If this is the only bin that fits the current item, penalize it less to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // High penalty for opening a new bin (bin_residual == bin_capacity) 
    // unless the mean_residual of current bins is very low (indicating they are nearly full).
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // Coupling: penalize large residuals more as the stream nears the end to force compaction.
    score += (post_res / bin_capacity as f64) * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize residuals between 1 and 9, as they are too small for most items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
