    // Lookahead logic: if the next item is large, prioritize keeping larger residuals.
    // If the next item is small, prioritize tighter fits (smaller residuals).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // This placement makes the next item impossible to fit here; penalize if it's a tight squeeze.
            score += 15.0;
        } else {
            // This placement keeps the next item viable; reward based on how well it fits.
            score -= (next_item_size as f64 / (post_residual + 1) as f64) * 10.0;
