    }

    // Harmonic class logic: favor filling bins to specific thresholds (e.g., 1/2, 1/3, 1/4 of capacity).
    // Bins ending near 0, 25, 33, or 50 residual are often better for future packing.
    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // If this is the only bin that can fit the item, we are forced to use it.
    // Reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discourage opening too many bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is weighted by how much of the stream is left.
        score += 25.0 * (1.0 - progress);
    }

    // Balance against the mean residual of current bins to maintain uniformity.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
