    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Global state: If we are late in the stream, be more aggressive about filling existing bins
    // to avoid leaving too many partially filled bins open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the fitting_bins_count is low or the current fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if we have existing options
            score += 60.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // Reward opening a new bin if it's the only way to fit the item
            score -= 10.0;
        }
    }

    // 5. Balance existing bins: If the current bin's residual is way above the mean, 
    // it's a good candidate to fill up (Best Fit logic).
    if bin_residual > (mean_residual as u32) {
