    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it based on how many existing bins could have taken the item.
    // This discourages opening new bins unless the existing fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 50.0 + (fitting_bins_count as f64 * 25.0);
    } else {
        // 2. Penalty for creating "dead space": residuals that are too small to fit common items (10-20 range).
        if post_residual < 10 {
            score += 20.0;
        }

        // 3. Lookahead Matching: Reward placing items such that the next item fits perfectly or well.
        // We favor bins that leave enough room for the next item (if it exists).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward: Reducing the post_residual to a value close to zero after next_item_size is placed.
                let gap_after_next = (post_residual - next_item_size) as f64;
                score -= (100.0 - gap_after_next) * 0.5;
            } else {
                // Penalty: If the next item won't fit, we penalize based on how much wasted space is left.
                score += post_residual as f64 * 0.3;
            }
        }

        // 4. Global balance: If we have many open bins, penalize residuals that deviate from the mean
        // to encourage packing bins to similar levels (Best-Fit style).
        if open_bins_count > 1 {
            let deviation = (post_residual as f64 - mean_residual).abs();
            score += deviation * 0.2;
        }
    }

    // 5. Progression factor: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prefer tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if the current mean residual is already quite low,
        // or if we are forced to (fitting_bins_count == 0).
        // Heavily penalize opening a new bin early in the stream.
        score += 25.0 + (mean_residual * 0.5) + (1.0 - progress) * 50.0;

        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // If the bin is already open, evaluate the lookahead potential
        if next_item_size > 0 {
            // If the next item fits into the current post_residual, reward this bin
            if post_residual >= next_item_size {
                score -= 15.0;
            } else {
                // If it doesn't fit, penalize based on how much space is "wasted"
                // relative to the next item size
                score += (next_item_size as f64 - post_residual as f64) * 0.2;
            }
        }

        // Penalty for creating a "fragment" (small residual that is hard to fill)
        // Values < 10 are often considered dead space in bin packing
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Adjust for the global state: if we have many bins open, try to consolidate
    // by preferring bins that are already partially full (lower residual)
    score += (open_bins_count as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize creating "dead space" (small residuals that cannot fit common items).
    // The penalty is non-linearly scaled by the progress of the stream to prioritize
    // tight packing early and allow more flexibility as the stream concludes.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the lookahead item size.
    // This helps in preparing for the next item, coupling the current placement
    // with the expected upcoming demand.
    let lookahead_alignment = if next_item_size > 0 {
        (post - next_item_size as f64).abs() * 0.5
    } else {
        0.0
    };

    // Favor bins that have a residual close to the global mean, 
    // discouraging extreme outliers in bin fullness.
    let mean_alignment = (post - mean_residual).abs() * 0.2;

    // Penalty for opening a new bin (where bin_residual == bin_capacity)
    // proportional to the current number of open bins and total stream progress.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Final score: base post_residual (Best Fit strategy) modified by
    // dynamic penalties/rewards. Lower is better.
    post + dead_space_penalty + lookahead_alignment + mean_alignment + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that leave small, unusable fragments
    // We target residuals that are likely to be "wasted" (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: Reward placements that leave room for the next item
    // If the next item can fit perfectly into the new post_residual, drastically reduce score
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Reward "tight" packing for the next item
            score -= (100.0 - gap as f64) * 0.5;
        } else {
            // Penalize leaving a gap that is too small for the next item
            score += 20.0;
        }
    }

    // 3. Structural Efficiency: Prefer bins that align with the global mean residual
    // This helps keep bins balanced, preventing a mix of very full and very empty bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Threshold Logic: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if fitting_bins_count is low
        // This is a "Best Fit" refinement: only open if existing bins are poor matches
        score += 40.0;
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 2.0;
        }
    } else {
        // Reward filling existing bins to reduce open_bins_count
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // 5. Modulo-based "harmonic" packing: 
    // Penalize odd remainders that don't divide well into standard item sizes (e.g., 20, 25, 33, 50)
    if post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize residuals that are too small to fit typical future items
    // If residual is < 10, it's likely "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
