    // 4. Mean Residual balancing: Favor bins that keep the overall mean residual consistent
    // This prevents creating many bins with very different fill levels.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 5. Stream Progression: Be more conservative with new bins as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
