        let progress = step_index as f64 / total_items as f64;
        score += 40.0 - (item_size as f64 * 0.4) - (progress * 10.0);
    }

    // 5. Critical Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Favor small post_residual (Best-Fit principle).
    // Penalize large gaps that are likely to become "dead space".
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin heavily to minimize fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
