        score += 40.0 * (1.0 - progress);

        // If many bins are already open, discourage opening another unless necessary.
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Global State Balancing: Use mean_residual to avoid creating bins 
    // that deviate significantly from the current average density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency Adjustment: If this is the only bin that can fit the item, 
    // prioritize it to avoid forced new-bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
