    }

    // 6. Extreme Fit Bonus: Perfect fits (100% capacity) are optimal.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle), but we modify it based on context.
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is small but > 0, 
    // it is often worse than a perfect fit (0). We add a non-linear curvature 
    // to penalize fragments that are too small to fit common item sizes.
    // 1.0 / (post_res + 1.0) creates a curve that spikes as post_res approaches 0.
    score += 50.0 / (post_res + 1.0);

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 && (next_item_size as f64) > post_res {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as we reach the end of the stream (progress -> 1.0), 
    // we become significantly more aggressive about filling existing bins 
    // to avoid leaving trailing bins open.
    if fitting_bins_count > 0 {
        score -= (10.0 * progress) * (1.0 / (fitting_bins_count as f64));
    }

    // New Bin Logic: If this is a new bin (bin_residual == bin_capacity), 
    // we penalize it heavily early in the stream, but ease the penalty 
    // if we have too many open bins that are poorly packed (high mean_residual).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        score += mean_residual * 0.5;
    }

    // Interaction term: penalize bins that deviate far from the mean packing density
    // as it creates fragmented space across the system.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
