    }

    // 5. Global Balance: Use mean_residual to avoid over-filling bins if many are open.
    // If current bin's residual after placement is much lower than the mean, it's a "tight" fit.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Modulo Harmonic Weighting:
    // Reward placements that leave a residual which is a multiple of 10,
    // as these are statistically more likely to accommodate common item sizes.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
