        // If the bin's resulting residual is much smaller than the mean, it's a good fit.
        score += (post_residual as f64 - mean_residual).powi(2) * 0.1;
    }

    // Lookahead interaction:
    // If the next item is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a residual that cannot fit the next item.
            score += (next_item_size - post_residual) as f64 * 1.2;
        } else {
            // Reward creating a residual that can perfectly accommodate the next item.
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.5;
        }
    }

    // Encourage using bins that are already open over starting new ones, 
    // especially when fitting_bins_count is low.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead zones": if post_residual is < 10, it's often unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 3. Harmonic Lookahead: If the next item can fit in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 33, 50).
    let mod_val = post_residual % 25;
    if mod_val == 0 {
        score -= 10.0;
    }

    // 5. If this is the only bin that fits, we must take it (prevent opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Avoid opening a new bin unless the remaining space in existing bins is highly fragmented.
    // If we are evaluating the empty bin (new bin candidate):
    if bin_residual == bin_capacity {
        // High penalty to open a new bin if we have many empty/partially full bins already.
        score += (open_bins_count as f64) * 5.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 7. Balance load across bins by penalizing bins that deviate significantly from the mean_residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
