    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead mechanism: prioritize bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item to keep packing density high
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize if this placement makes the next item impossible to fit
            score += (next_item_size as f64) * 0.4;
        }
    }

    // 3. Dynamic Thresholding: discourage opening new bins as the stream nears completion
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 25.0;
        // Increase penalty as we progress to avoid fragmentation near the end
        score += (progress * 50.0);
    }

    // 4. Global State Awareness: if we have many open bins, penalize creating another
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Anti-Fragmentation: if this is the last fitting bin, prioritize it to avoid 
    // creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Mean Residual Balancing: avoid bins that deviate significantly from average density
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post.powf(1.5);

    // Penalty for opening a new bin: exponential growth as we near the end of the stream
    if bin_residual == bin_capacity {
        score += 100.0 * (1.0 + 5.0 * progress.powi(2));
    }

    // Lookahead: If next_item_size is large, penalize small post_residuals that would "waste" a bin
    // by leaving too little space for the next item (creating unusable dead space).
    if next_item_size > 0 {
        let wasted_potential = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 2.5
        } else {
            0.0
        };
        score += wasted_potential;
    }

    // Balance: Favor bins that align with the current mean_residual to keep bin states uniform
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Scarcity: If only one bin fits, prioritize it to avoid opening a new bin prematurely
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

