    // We heavily penalize large post_residuals to minimize fragmentation.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class logic: Identify "gaps" that accommodate specific future sizes.
    // If next_item_size fits in the post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
