    }

    // 3. Thresholding: Avoid creating "dead" space (remnants < 10 are often unusable)
    // If the post_residual is in the 1-9 range, it's a "fragmentation trap".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Lookahead context: If this is the last fitting bin, prioritize it to avoid 
