    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. New bin handling: 
    // If the bin is empty (bin_residual == bin_capacity), set a baseline cost.
    // We only open a new bin if the best existing bin has a poor fit (high post_residual).
    if bin_residual == bin_capacity {
        score = 45.0 + (item_size as f64 * 0.2);
    }

    // 6. Global density balance:
    // If the current bin's residual is much higher than the mean, penalize it
    // to force consolidation into more "filled" bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
