    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            // If we MUST open a new bin, normalize the score to be competitive.
            score = 50.0;
        }
    }

    // 4. Balance the packing density relative to the mean_residual.
    // If the current bin is significantly emptier than the average, prefer filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // tighten the penalty for leaving any space at all.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
