    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As the stream nears completion, we become more aggressive in forcing tight fits.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(3) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward placing items into bins that result in a residual close to the lookahead item size.
    // This maximizes future compatibility.
    let lookahead_alignment = if next_item_size > 0 {
        (post - next_item_size as f64).abs().powf(1.5)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // based on how many bins are already open and how much space is currently wasted.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (mean_residual * 0.5) + (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // If this is the last fitting bin, we should prioritize it to avoid opening a new bin unnecessarily.
    let last_chance_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    let score = post + fragmentation_penalty + lookahead_alignment + new_bin_penalty + last_chance_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
