    // If the post_residual is positive but less than 10 (smallest item), it's highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins where the post_residual can accommodate the next item perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that have just enough space for the next item without being too wasteful.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize if the next item won't fit in this bin.
            score += 5.0;
        }
    }

    // 3. Balance bin utilization against the global mean.
    // If we are below the mean, we are "under-packing" this bin relative to others.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 4. Force Best-Fit Behavior:
    // If this is a new bin, penalize it heavily unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score -= 20.0;
        }
    }

    // 5. Dynamic scaling based on stream progression.
    // As the stream nears the end, prioritize tightly packing existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current residual after placement
    let r = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual)
    let mut score = r;

    // 2. Penalty for creating "dead zones" (unusable space < 10, assuming 10 is min item size)
    // If post_residual is between 1 and 9, it's highly likely to be wasted.
    if r > 0.0 && r < 10.0 {
        score += 50.0;
    }

    // 3. Lookahead Logic: 
    // If we have a next item, check if this bin can accommodate it after the current one.
    if next_item_size > 0 {
        if r >= next_item_size as f64 {
            // Reward bins that can fit the next item (Best-Fit-Lookahead)
            score -= 25.0;
        } else {
            // Penalize bins that block the next item if there are other bins that could fit it
            score += 15.0;
        }
    }

    // 4. Global State Awareness:
    // If we are late in the stream, prioritize closing bins to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && r < 20.0 {
        score -= 10.0 * (1.0 - progress);
    }

    // 5. Thresholding the "New Bin" vs "Existing Bin" decision:
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current existing bins force a bad fit (e.g., r < 10)
        // or if we have no fitting bins at all.
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item
            score += 60.0;
        } else {
            // If no existing bin fits, prioritize the new bin
            score -= 100.0;
        }
    }

    // 6. Dynamic Scaling based on Mean Residual:
    // If our average bin is very empty, try to fill existing bins rather than opening new ones.
    if mean_residual > 40.0 {
        score += (mean_residual - 40.0) * 0.5;
    }

