    let tightness = 1.0 - progress;
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is high
        // or if we are very early in the stream.
        score += (mean_residual * 0.5) + (tightness * 50.0);
    }

    // Penalty for spreading items across too many bins early on
    if open_bins_count > 0 {
        score += (open_bins_count as f64 / (1.0 + progress * 10.0)) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
