    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Balance against mean_residual: avoid outlier bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Progress factor: As we near the end, prioritize filling existing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
