    // better than the average of other bins, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Thresholding: Discourage opening a new bin unless the current
    // fits are extremely poor (i.e., would result in a very small post_residual).
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin.
        score += 45.0;

        // If the item is large (e.g., > 70), opening a new bin is better than
        // wasting a tight bin.
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 6. Urgency: If this is the only fitting bin, prioritize it to avoid
    // unnecessary new bin overhead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 7. Progression factor: As the stream nears completion, prioritize 
    // closing bins over efficiency.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead zones" (residuals too small for the minimum expected item)
    // Small residuals (1-9) are often wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Lookahead optimization (k=2)
    // If the next item exists, favor bins that can accommodate it after current placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for "perfect" sequential fit
        } else if post_residual > 0 {
            score += 15.0; // Penalty if current placement blocks the next item
        }
    }

    // 3. Dynamic "Best-Fit" pressure
    // As the stream progresses, become more aggressive in filling bins (lower score = prioritize).
    // If a bin is nearly full, reward it to consolidate space.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 4. Global state management
    // If we have many open bins, penalize opening a new one.
    if is_new_bin {
        score += 20.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    } else {
        // If this is the only bin that fits, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // If this bin's residual is significantly better than the mean, reward it
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual (tighter fit) is generally better (Best-Fit principle).
    let mut score = post;

    // Penalty for leaving "sliver" space (1-9) that is likely unusable for future items (10-80 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item cannot fit in the post_residual, punish this bin choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Dynamic adaptation: As the stream progresses, prioritize filling existing bins 
    // more aggressively to minimize fragmentation towards the end.
    let fill_urgency = progress * 40.0;
    score += fill_urgency * (open_bins_count as f64 / (fitting_bins_count as f64 + 1.0));

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold penalty
    // to discourage opening a new bin unless the existing ones are extremely poor fits.
    if bin_residual == bin_capacity {
        // The "New Bin" cost is scaled by the mean residual of existing bins.
        // If existing bins have huge gaps, opening a new one is less expensive.
        score += 45.0 + (mean_residual * 0.5);
    }

    // Smooth non-linear coupling: penalize bins that deviate significantly from the mean_residual
    // to encourage uniform packing density across the bin set.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones' that cannot fit common small items (e.g., < 20).
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 - (post_residual as f64 * 2.0);
    }

    // Favor bins that leave enough room for the lookahead item (next_item_size).
    // If next_item_size is large, we want to prioritize bins with larger residuals.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize if we block the next item from fitting here.
            score += 15.0;
        }
    }

    // Harmonic class logic: prioritize filling bins to specific thresholds (e.g., 1/2, 1/3 capacity).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.75 {
        score -= 10.0; // Reward consolidation
    }

    // Penalize opening a new bin if the item could fit in existing bins,
    // unless the current bin is very empty and the item is large.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 50.0; // Strong disincentive to open new bins prematurely
        } else {
            score -= 5.0; // Baseline for new bin
        }
    }

    // Adjust for the progress of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
