pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) specifically as the stream progresses.
    // Near the end of the stream, prioritize aggressive consolidation (smaller residuals).
    let fragmentation_penalty = (10.0 / (post + 1.0)) * (1.0 + progress);

    // Lookahead logic: if the next item fits into the current post_residual, 
    // significantly reward this placement (negative score).
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening new bins when space is available.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
