    };

    // Interaction between mean_residual and current post: 
    // Prefer bins that stay closer to the global mean to maintain uniformity.
    let uniformity_score = (post - mean_residual).abs() * 0.5;

    post + fragmentation_penalty + lookahead_bonus + new_bin_penalty + uniformity_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
