    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 4. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // If other bins can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the average.
        // This keeps the "fill level" consistent across active bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 6. Final progression scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // However, if the residual is very small (< 10), it becomes "dead space" that cannot fit any item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // Penalty for creating unusable slivers
    }

    // 2. Lookahead Coupling: If the post_residual can accommodate the next item, 
    // prioritize this bin heavily to maximize bin utilization density.
    if next_item_size > 0 && post_residual >= next_item_size {
