    // If this bin is significantly emptier than the average, we penalize it to keep
    // residuals uniform across bins (improving chances for future larger items).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. New Bin Logic: If we are forced to open a new bin (bin_residual == bin_capacity),
