    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        score += 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: If next_item_size is large, penalize small post_residuals 
    // that leave no room for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
