    }

    // Global density balancing: 
    // If the mean residual is high, we are being too wasteful; penalize large post_residuals.
    // If the mean residual is low, we are tight; favor placements that keep the bin balanced.
    let density_factor = (mean_residual / bin_capacity as f64) * 10.0;
    score += (post_residual as f64 * density_factor) / 10.0;

    // Non-linear curvature: Penalize mid-range residuals that are "awkward" 
    // (too small to fit common items, but too large to be considered 'full').
    let waste = post_residual as f64;
    score += (waste * waste) / 50.0;

    score
