        let residual_after_next = post_residual - next_item_size;
        if residual_after_next < 5 {
            score -= 20.0;
        }
    }

    // Harmonic Thresholding: If post_residual is a multiple of common item sizes, 
    // it's likely to be filled more efficiently later.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // New Bin Penalty: If this is a new bin (residual == capacity), penalize it 
    // heavily unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 85.0;
        } else {
            score -= 20.0; // Accept opening a new bin if it's the only choice
        }
    }

    // Dynamic Scaling: As the stream progresses, favor packing tighter to avoid fragmentation
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Penalty for excessive open bins to encourage consolidation
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
