    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher if other bins could have taken it.
        // We modulate this by progress to encourage consolidation.
        score += 15.0 + (progress * 40.0) + (fitting_bins_count as f64 * 5.0);
    } else {
        // For existing bins, favor bins where the remaining space is close to the 
        // expected next item size (lookahead) to minimize wasted gaps.
        if next_item_size > 0 {
            let lookahead_diff = (post - next_item_size as f64).abs();
            score += lookahead_diff * 0.5;
        }

        // Penalty for bins that deviate significantly from the mean residual
        // to keep bin fill levels homogeneous across the active set.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Secondary constraint: if this is the last chance to fit the item in an open bin,
    // reduce the score (reward) to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic penalty: Heavily penalize post_residuals that are small but unusable (e.g., < 10)
    //    unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; 
    }

    // 3. Lookahead integration: 
    // If we have a next item, favor bins that can accommodate it later.
    // If the current post_residual is smaller than the next item, we penalize it
    // because it becomes a "dead" zone for that specific item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that can fit the next item perfectly
            if (post_residual - next_item_size) < 5 {
                score -= 15.0;
            }
        }
    }

    // 4. Thresholding: Avoid opening a new bin unless the current best fit is truly abysmal
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only open a new bin if we have many bins open and the mean residual is high,
        // or if the item is large and fits poorly into existing fragments.
        if open_bins_count > 0 && (mean_residual > 20.0 || item_size > 60) {
            score = 40.0;
        } else {
            score = 100.0; // Penalty to prevent premature bin opening
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize packing tighter to reduce trailing empty bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    // 6. Fitting count awareness: If this is the last chance for the item, 
    // reduce penalty to ensure it gets placed.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit any future items (assuming min possible item size is ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Penalize opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity) and fitting_bins_count > 0, 
    // we heavily penalize it to force reuse of existing space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Lookahead Alignment: Favor bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "Perfect Fit" potential
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If the next item won't fit, we penalize slightly to prefer bins that might fit it.
            score += 5.0;
        }
    }

    // 4. Global Density Awareness: If we have many open bins, penalize creating more.
    // Normalize open_bins_count against the progress of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 5. Residual Balancing: If this bin's post_residual is significantly better than the mean, 
    // favor it to keep bins tightly packed.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large gaps remaining in a bin.
