    // If the current bin's post_residual is significantly smaller than the 
    // average residual of other bins, it might be a "dead" bin.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 25.0; // Penalize creating "slivers" that are hard to fill.
    }

    // 5. Progression awareness: 
