}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. New-bin thresholding: Only open a new bin if the best available fit is extremely poor
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only want to open a new bin if existing bins would leave a "dead" gap 
        // that is too small for future items.
        if fitting_bins_count == 0 {
            score = 50.0; // Force opening if no other choice
        } else {
            // Penalize opening a new bin unless the remaining items are likely to be large
            let progress = step_index as f64 / total_items as f64;
            score = 150.0 - (progress * 50.0);
        }
    } else {
        // 3. Lookahead optimization: If next_item_size fits in the post_residual, 
