        }

        // 4. Global state optimization: Avoid leaving small slivers.
        // If post_residual is in the "danger zone" (1..9), penalize it unless it's 0.
        if post_residual > 0 && post_residual < 10 {
            score += 35.0;
        }

        // 5. Dynamic balancing: If we have many open bins, prioritize packing 
        // tightly into bins that are already "half-full" to consolidate.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 10.0;
        }

        // 6. Final adjustment: Prefer bins that align with the mean residual 
        // to keep the bin distribution uniform.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize opening a new bin heavily unless we are in the early stages or have no choice
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 200.0 + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Best-fit/Worst-fit balancing: 
    // We want to minimize post_residual, but avoid "dead-end" residuals (very small gaps < 10)
    // that are unlikely to accommodate future items.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size exists, penalize residuals that can't fit it
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Interaction between fitting_bins_count and mean_residual to cluster items
    // and keep the mean_residual of open bins relatively balanced.
    let cluster_pressure = (post_res - mean_residual).abs() * 0.5;

    let score = post_res 
        + new_bin_penalty 
        + dead_space_penalty 
        + lookahead_penalty 
        + cluster_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
