    // We specifically penalize the "New Bin" case (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // If we have other options, make opening a new bin expensive
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            score -= 10.0;
        }
    }

    // 2. Lookahead Coupling: If next_item can fit in current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
    }

    // 3. Global State: If mean_residual is high, we are wasting space; be more conservative
    if mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.5;
    }

    // 4. Scarcity Logic: If few bins can fit this item, prioritize keeping it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // 5. Final Calibration: Small residuals (dead space) are the primary enemy
    // If post_residual is very small (< 5), it's often a "dead" bin.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    // We penalize small post_residuals (creating "slivers") unless we are near the end of the stream.
    // Penalty is scaled by the probability of the next item fitting into the created gap.
    let sliver_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 - progress) * 2.0
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large, avoid bins that leave just enough space 
    // to be "almost" full but not enough for the next item.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Global state awareness: If we have many open bins, prioritize packing into the tightest ones.
    // As progress increases, we become more aggressive in closing bins (lower score for lower post_residual).
    let density_factor = (open_bins_count as f64 / 10.0) * progress;

    // New bin threshold control: 
    // If bin_residual == bin_capacity, this is a new bin.
    // We penalize opening a new bin heavily unless the current open bins are very poorly utilized.
    let score = if res == bin_capacity as f64 {
        let avg_waste = bin_capacity as f64 - mean_residual;
        // Only open new if the average waste in existing bins is high, or if we have no fitting bins.
        if fitting_bins_count == 0 {
            10.0 // Base cost of opening a new bin
        } else {
            10.0 + (avg_waste * 0.5) + (progress * 20.0)
        }
    } else {
        post + sliver_penalty + lookahead_penalty + (density_factor * post)
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor bins that leave the least space (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: Encourage placements that leave room for the next item
    // If post_residual is slightly less than next_item_size, it's a "dead zone".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Severe penalty for creating a bin that can't fit the next item
            score += 40.0;
        } else if (post_residual - next_item_size) < 10 {
            // Reward "tight packing" (perfect match) for the next item
            score -= 25.0;
        }
    }

    // 3. Harmonic Class Logic: Prefer bins that leave residuals matching common item sizes
    // This reduces fragmentation by creating "standard" remaining capacities.
    let residual_mod = (post_residual % 25) as f64;
    score += residual_mod * 0.8;

    // 4. Thresholding: Avoid opening a new bin unless necessary
    // If this is a new bin (residual == capacity), penalize it based on how many 
    // existing bins could have fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong discouragement to open a new bin if others are available
            score += 150.0 + (fitting_bins_count as f64 * 20.0);
        } else {
            // Neutralize score for essential new bin opening
            score -= 30.0;
        }
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize closing bins
    // over keeping many partially filled bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to fit common items
    // If the post_residual is between 1 and 9, it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins if we have existing capacity
    // If this is a new bin (bin_residual == bin_capacity), increase cost significantly
    if bin_residual == bin_capacity {
