            let gap = post_residual - next_item_size;
            if gap < 5 {
                score -= 20.0;
            }
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Balance: Penalize creating bins with residuals significantly lower than the mean
    // This promotes packing items into bins that have "average" remaining space, keeping bins uniform.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // 1. Base Score: Minimize post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin unnecessarily
    // If the bin is new, penalize based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead Matching (The "Aggressive 2-step" component)
    // If we have a next item, check if it fits in the post_residual space.
    // If it fits, we reward the bin that creates a "perfect" or "near-perfect" pair.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff));
        } else {
            // Penalize creating a bin that is too small for the next item
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing
    // We want to keep the bins balanced. If this bin's post_residual is significantly 
    // higher than the current mean, penalize to push items into tighter bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Urgency Calibration
    // If this is the only fitting bin, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive tightening
    // As the stream progresses, prioritize tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
