    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = post_residual - next_item_size;
        if fit_gap < 5 {
            score -= 30.0; // Strong reward for high-density packing
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary, but penalize
    // excessive fragmentation across too many bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current number of open bins is low, 
        // or if it's the absolute last resort.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // Reward packing into existing bins, especially those with smaller residuals 
        // to keep larger bins available for larger items.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
