            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic constraint: If we are late in the stream, be more aggressive 
    // about filling existing bins rather than opening new ones.
    if is_new_bin {
        // High penalty for opening a new bin if we have fitting options
        let density_penalty = (open_bins_count as f64 / 10.0).sqrt();
        score += 40.0 + (progress * 30.0) + (density_penalty * 10.0);

        // If this is the only bin that fits, we MUST take it (or open new)
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reward bins that keep the mean residual balanced
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Harmonic Class Logic: If post_residual is small (e.g., < 10), it's likely a "good" fit.
    // We heavily penalize post_residuals that are just large enough to be unusable (e.g., 1..9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; 
    }

    // 3. Lookahead Logic: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize opening a new bin unless the post_residual of existing bins is consistently poor.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open first bin
        } else {
            // Only open a new bin if the mean_residual of current bins is already quite low
            // or if we are at the very end of the stream.
            score += 35.0 + (mean_residual * 0.5);
        }
    }

    // 6. Harmonic refinement: Use modulo to favor bins that reach exact capacity thresholds
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps smaller than the smallest likely item, 
    // or specifically gaps that can't fit the lookahead item).
    if post_residual < next_item_size && next_item_size > 0 {
        score += 50.0 + (next_item_size as f64 - post_residual as f64);
    }

    // 2. Strict dead space avoidance: heavily penalize tiny unusable slivers (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 3. Open bins pressure: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have fitting bins, discourage opening a new one unless the fit is terrible.
        if fitting_bins_count > 0 {
