        }
    }

    // 4. Lookahead optimization: If current post_residual is a perfect fit for next_item_size,
    // reward this choice to consolidate space usage.
    if next_item_size > 0 && (post_residual == next_item_size) {
        score -= 40.0;
    }

    // 5. Global state normalization: adjust score based on how full the average bin is.
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
