    // Avoid opening a new bin if we have existing capacity, unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only pick if fitting_bins_count is low or if current mean_residual is very high (wasteful).
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        }
        // Dynamic thresholding: as we reach the end of the stream, 
        // become more conservative about opening new bins.
        score += progress * 30.0;
    } else {
        // If we are placing in an existing bin, reward bins that are closer to the mean residual.
        // This promotes uniform distribution of space across open bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

