}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We add a non-linear penalty for creating "dead space" that is too small to fit common items.
    // Small residuals (1-9) are highly penalized as they are difficult to fill later.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 / (post_res + 1.0)
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large, favor bins that have enough room for it.
    // We penalize bins that would make fitting the next item harder.
    let next_fit_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Progression scaling: As we approach the end of the stream, prioritize aggressive packing (lower residual).
    // Early on, we accept slightly larger residuals to keep options open.
    let progress_modifier = (1.0 - progress) * (mean_residual - post_res);

    // New bin avoidance: If we have fitting bins, heavily penalize opening a new bin.
    let new_bin_penalty = if bin_residual == bin_capacity && open_bins_count > 0 {
        150.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Combine terms:
    // We want to minimize the score, so penalties are added.
    let mut score = post_res + dead_space_penalty + next_fit_penalty + progress_modifier + new_bin_penalty;

    // Favor bins that have a residual closest to the average to maintain uniform distribution across bins.
    score += (post_res - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
