    // 3. New Bin Threshold: If we are forced to open a new bin, make it expensive
    // unless the current open bins are all very poorly suited for future items.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but scale down as we approach end of stream
        score += 45.0 * (1.0 - progress);
