    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Penalty for creating "slivers" (very small unusable space)
    // Slivers are typically < 10, as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
