    // If considering a new bin, penalize it based on how many open bins already exist
    // to encourage bin consolidation (Best-Fit Decreasing behavior)
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // Only open a new bin if we are forced to or if the average residual is very low
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Factor in progress: as we near the end of the stream, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to fit common items
    // If the residual is positive but less than 10 (the minimum item size), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Coupling: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available.
    // This discourages the "new bin" candidate unless the fit is exceptionally good.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Density: If this is the only fitting bin, prioritize it to avoid opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: As the stream progresses, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic Best-Fit objective (minimizing post_residual)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 25.0;
        // If we have many open bins already, make opening a new one very expensive
        score += (open_bins_count as f64) * 2.0;
    }

    // Lookahead logic: if we can fit the next item into the post_residual space, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further refine: if post_residual is close to next_item_size, it's an excellent fit
        let waste = (post_residual - next_item_size) as f64;
        score += waste * 0.5;
    }

    // If this is the last fitting bin, we are forced to use it or open a new one.
    // Reward using this bin heavily to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalty for creating fragments (very small residuals that are unlikely to fit future items)
    // 1-9 is often considered 'dead space' in bin packing.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Adjust based on the global state of the packing
    // If the mean residual is high, we have plenty of space; be more selective.
    // If the mean residual is low, we are packing tightly; prioritize filling gaps.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals that create "slivers" (< 10) 
    // unless it's a perfect fit (0 residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global Density Management: If we have many open bins, penalize opening new ones.
    if is_new_bin {
        score += (open_bins_count as f64) * 15.0 * (1.0 - progress);
    } else {
        // Encourage filling bins that are already below average density
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // 4. Criticality Filter: If this is the only bin that fits the item, 
    // incentivize it to prevent forced new-bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Time-Horizon Scaling: As the stream nears the end, prioritize tight packing 
    // (minimal post_residual) to avoid stranding items.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Reward bins that leave very little space (Best Fit)
    // Penalize bins that leave "fragmented" space (e.g., 1-9 units)
    let fragmentation_penalty = if post > 0.0 && post < 10.0 { 15.0 } else { 0.0 };

    // Non-linear coupling: As the stream progresses, prioritize tighter packing
    // to avoid being left with many open bins containing small fragments.
    let tightness_factor = (1.0 + progress) * post.powf(1.2);

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals
    // that won't fit the next item.
    let lookahead_penalty = if next_item_size > post_residual && post_residual > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // New bin logic: Only open a new bin if the current options are very poor.
    // We heavily penalize opening a new bin early in the stream, 
    // but allow it if the fitting bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // discourage new bins if existing ones exist
            (50.0 + (progress * 100.0)) * (1.0 / (fitting_bins_count as f64 + 1.0))
        }
    } else {
        0.0
    };

    // Influence of mean_residual: Encourage balancing residuals across bins
    let balance_penalty = (post - mean_residual).abs() * 0.2;

    tightness_factor + fragmentation_penalty + lookahead_penalty + new_bin_penalty + balance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in smaller post_residual (tighter packing).
    // The base score is post_residual. We refine this based on harmonic/modulo pressure.

    // 2. Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger future items from fitting.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Significant penalty for creating unusable slivers
    }

    // 3. Lookahead Harmonic Coupling: 
    // If the next item fits into the current post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic class logic: Favor placements that leave space as a multiple of common item sizes (e.g., 20, 25, 33).
    // This helps keep bins "aligned" for potential future fits.
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.2;

    // 5. Global density pressure: 
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If this bin is the last chance for the current item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 6. Progression normalization: 
    // As the stream progresses, prioritize closing bins (lower mean_residual) to reduce bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps that cannot fit future items.
    // A gap < 10 is almost always unusable given item range 10-80.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is in the "unusable" range [1, 9], 
    // add a heavy penalty to discourage creating these gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Coupling: If a next item exists, reward bins that can accommodate it.
    // If post_residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that maintain enough room for the next item
            score -= 5.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many already open.
    // If this is a new bin (residual == capacity), add a penalty proportional to current open_bins_count.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item (fitting_bins_count == 1),
    // heavily prioritize it to prevent creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual balancing: Prefer bins that are already closer to the mean to keep utilization uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless absolutely necessary or if existing bins are too full
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; 
        } else {
            score -= 50.0; 
        }
    }

    // 2. Lookahead: Reward placements that leave exactly enough space for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < next_item_size {
            // Severe penalty for stranding the next item
            score += 80.0;
        }
    }

    // 3. Fragmentation control: penalize residuals that are too small to be useful (under 10)
    // but reward residuals that align with the current mean to keep bins balanced.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Density focus: Favor bins that are already well-utilized
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 5. Progression scaling: As we reach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize the post-residual (Best Fit) but penalize "fragmentation" 
