        score -= (open_bins_count as f64) * 0.5;

        // 5. Dynamic time horizon: As the stream progresses, become more aggressive 
        // about filling bins tightly to avoid trailing fragments.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;

        // 6. If this is the last chance to fit the item in an existing bin, 
        // reward taking it to avoid opening a new bin.
        if fitting_bins_count == 1 {
