        score += 40.0 * (1.0 + progress.powi(2));

        // If we have other bins that could fit this, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward filling bins that are already "tight" relative to the mean
        // This encourages clustering small items in already-full bins
        if (bin_capacity - bin_residual) > (mean_residual as u32) {
