    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 20.0);
        // Only open if very few bins are available or current fits are terrible.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly from the average
    // to keep the packing density uniform across all active bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded ("dead space")
    // A residual between 1 and 9 is often unusable for items >= 10.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that align with the next item size (Lookahead coupling)
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -(post - next_item_size as f64).exp() * 0.5
    } else {
        0.0
    };

    // Adaptive pressure: as the stream progresses, prioritize tighter packing
    // to avoid leaving too many bins open.
    let progress_pressure = progress * (post / bin_capacity as f64) * 20.0;

    // Favor bins that maintain a residual close to the current mean_residual,
    // encouraging uniform bin filling (load balancing).
    let uniformity_score = (post - mean_residual).abs() * 0.1;

    // If this is the only bin that fits, we are forced to take it; 
    // otherwise, penalize opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit is extremely poor in all other bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 { 0.0 } else { 40.0 - (progress * 10.0) }
    } else {
        0.0
    };

    post + dead_space_penalty + lookahead_bonus + progress_pressure + uniformity_score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
