    // An ideal remainder is 0, followed by values larger than the largest common item (80).
    // We use a quadratic penalty for remainders in the range [1, 25] to discourage fragmenting.
    let dead_zone_penalty = if post_residual > 0 && post_residual <= 25 {
        (25.0 - post_res).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, we prefer larger post_residuals now.
    // Otherwise, we prioritize Best Fit (minimizing post_residual).
    let lookahead_factor = if next_item_size > 60 {
        -1.5 * (next_item_size as f64 / bin_capacity as f64) * post_res
    } else {
        0.5 * post_res
    };

    // Global state awareness: encourage using existing bins as the stream nears the end,
    // to avoid leaving partially filled bins stranded.
    let completion_bias = (1.0 - progress) * (open_bins_count as f64 * 5.0);

    // New bin candidate logic:
    // If this is a new bin (bin_residual == bin_capacity), score it based on 
    // the current density of open bins. We only open a new bin if the existing
    // fits are truly poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty to open new bin unless density is very low
        150.0 + (open_bins_count as f64 * 2.0) - (progress * 20.0)
    } else {
        // Existing bin score:
        // Combine the post-fit remainder, lookahead, and dead-zone avoidance.
        post_res + dead_zone_penalty + lookahead_factor + completion_bias
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize bins that leave residuals that are multiples of common item sizes.
    // A residual of 0 is perfect. A residual < 10 is often "dead" as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic alignment: prefer residuals that allow a wider range of future items.
    // Penalize residuals that are "awkward" (e.g., 15-25 range often blocks larger items).
    if post_residual >= 15 && post_residual <= 25 {
        score += 15.0;
    }

    // If this is the only bin that fits, we are forced to take it unless we want a new bin.
    // We make opening a new bin expensive relative to the mean residual of current bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += mean_residual * 0.8;
        } else {
            score -= 10.0; // Base cost to open the very first bin is low.
        }
    } else {
        // If fitting_bins_count is 1, this is the last chance for this item.
        // We reward keeping open_bins_count low.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Progress normalization: as we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
