    // Penalty for creating "dead space": gaps smaller than the smallest likely item (10).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Penalty for opening new bins when existing bins can fit the item.
    // Discourage new bin usage unless the current fit is exceptionally poor (post_residual < 10).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // Lookahead logic: If the next item is large, prefer bins that leave enough space for it.
    // If the current post_residual is smaller than the next item, we penalize the bin.
    if next_item_size > 0 {
