            score += 20.0;
        } else {
            // Reward bins that maintain enough room for the next item.
            score -= 15.0;
        }
    }

    // Pressure based on open bin count: discourage creating too many fragmented bins
    // as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // Favor bins that result in a residual closer to the global mean, 
    // keeping bin occupancy levels consistent.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize bins that leave tiny, unusable fragments (1-9).
    if post_residual > 0 && post_residual < 10 {
