    // is truly terrible (high residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very low,
        // suggesting that current bins are too full to accommodate future items.
        if open_bins_count > 0 && mean_residual > 15.0 {
