        }
    }

    // 4. Density Balancing: Favor bins that stay close to the running mean residual
    // to keep the distribution of remaining space uniform across bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency: As the stream nears the end, prioritize filling existing bins 
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
