    }

    // 5. New Bin Thresholding:
    // Only open a new bin if we are forced or if the current best fit is objectively terrible.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 65.0 + (progress * 20.0);
        } else {
            // No choice, must open new bin
            score = -100.0;
        }
    }

    // 6. Dynamic Scaling:
    // As the stream nears completion, become strictly Best-Fit to close gaps.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
