    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is too small to fit typical items, 
    // it's effectively wasted. We penalize small residuals more heavily as the stream progresses.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * (1.0 + progress * 5.0);
    }

    // Lookahead: if the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            // Penalty for stranding a large item
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Adaptive threshold: as the stream nears the end, become more conservative about opening new bins.
    // We reward keeping open bins count low by penalizing new bin creation (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    // Coupling with mean_residual: avoid bins that deviate too far from the average state,
    // to keep the bin distribution uniform.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.5;

    // If this is the last chance for this item (only one bin fits), 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
