        }
    }

    // 4. Density Balancing: Favor bins that keep residuals closer to the global mean,
    // avoiding bins that become outliers in terms of fullness.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression scaling: As we reach the end of the stream, prioritize 
    // tighter fits (Best Fit decreasing) to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 6. Harmonic Class Reward: Prefer leaving larger residuals if they are multiples 
    // of common item sizes (e.g., 20, 25, 50), which increases the probability 
    // of fitting future items perfectly.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
