    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0; // Strong penalty for opening new bins near the end.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We prioritize bins that leave the least space (Best-Fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin heavily to create a "combo" placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
    }

    // 3. Fragmentation Mitigation: If post_residual is too small to fit common items 
    // (e.g., < 10), it becomes "dead space". Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening new ones.
    // The "new bin" case is identified when bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 25.0;
        // Discourage opening a new bin if there are existing bins that can fit the current item.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Dynamic Thresholding: As we approach the end of the stream, 
    // be more aggressive about packing into existing bins to minimize total count.
    if progress > 0.8 {
        score -= (1.0 - mean_residual / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual is generally better (Best-Fit principle).
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill later).
    // If post_residual is small (e.g., < 10), it is often unusable for future items.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If this bin's post_residual is smaller than next_item_size, we penalize it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, we become more aggressive about filling existing bins
    // to avoid opening new ones.
    if fitting_bins_count == 1 {
        // High priority to use the last fitting bin to avoid opening a new one.
        score -= 20.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity).
    // We scale this penalty by the number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 1.5) + (progress * 10.0);
    }

    // Interaction term: balance mean_residual. 
    // If the current bin's post_residual is significantly higher than the global mean,
    // we penalize it to keep bins tightly packed.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // The base score (post_residual) already favors smaller gaps.

    // 2. Harmonic Class Logic: Penalize gaps that are unusable for common item sizes
    // We penalize post_residual values that are likely to become "dead space" 
    // (e.g., gaps < 10, since min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it creates a "perfect" bin (residual 0)
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // the alternative is forcing a very poor fit in an existing bin.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin, reduced by the number of open bins 
        // to encourage packing density.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting Bin Pressure: 
    // If only one bin can fit the item, we are forced to use it. 
    // If fitting_bins_count is high, we can afford to be pickier.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 2.0;
    }

    // 6. Global Efficiency: 
    // As the stream nears completion, favor closing bins (lower residual) 
    // to prevent leaving many half-empty bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual values that are too small to be useful
    // (e.g., < 10) but not zero. This creates a "Best-Fit" preference for tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Open bin pressure: Penalize opening new bins unless necessary.
    // If the bin is new (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 100.0; // Encourage opening a new bin if nothing else fits
        }
    }

    // 3. Lookahead optimization: If a next item exists, favor bins that leave 
    // enough room for it, or minimize the post_residual if the next item is large.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for leaving space for the next item
            score -= 30.0;
        } else if post_residual < 10 && post_residual > 0 {
            // Penalty if we create a gap that is useless for the next item
            score += 20.0;
        }
    }

    // 4. Global efficiency: Favor bins that keep the mean_residual low,
    // encouraging the usage of bins that are already partially filled.
    score += (mean_residual - post_residual as f64) * 0.5;

    // 5. Progression scaling: As we approach the end of the stream, 
    // be more aggressive in consolidating space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Penalize large post_residuals (wasted space).
    // We prefer post_residuals close to 0 (Perfect Fit).
    score += post_residual as f64 * 1.5;

    // 2. Lookahead optimization: If the next item can fit perfectly or near-perfectly 
    // into the remaining space, reward this bin choice.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
            // Strong reward for creating a bin that perfectly accommodates the next item
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize leaving a gap too small for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Prevent fragmentation: Penalize creating a bin with a residual smaller than 
    // the mean residual if it's not a near-perfect fit.
    if (post_residual as f64) < mean_residual && post_residual > 5 {
        score += 10.0;
    }

    // 4. Threshold control for opening new bins:
    // When bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "bad" fits (high average residual)
        // or if we have very few bins open (to avoid excessive fragmentation).
        if open_bins_count > 0 && mean_residual > 20.0 {
            score -= 5.0; 
        } else {
            // Make it harder to open a new bin if we have existing capacity
            score += 40.0;
        }
    }

    // 5. Emergency priority: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
