        score += (open_bins_count as f64) * 0.5;

        // 5. Dynamic horizon: As we reach the end of the stream, prioritize 
        // tighter packing to avoid straggler bins.
        if progress > 0.8 {
            score += post_residual as f64 * 0.5;
        }
    }

    // 6. Penalty for creating "dead zones" (small residuals that likely won't fit future items)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

