    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that can't fit the next item after the current one.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Global State Balancing:
    // As the stream progresses, prioritize closing bins (lower mean_residual) 
    // to avoid fragmentation, but keep bins open if they have high potential for the next item.
    let residual_penalty = (mean_residual - post) * progress;
    score += residual_penalty;

    // Boundary Logic for New Bin:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open it if the "cost" of fitting into existing bins is too high.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open new bin
        } else {
            // Only open a new bin if the best existing fit is extremely poor (large post_residual)
            // or if we are very late in the stream and need to consolidate.
            score = 50.0 + (progress * 20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

