    // If post_residual is < 10, it creates "dead space" that is unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Logic: If the next item is large, favor bins that leave enough room for it.
    // If the current placement leaves a gap that perfectly matches the next_item_size, boost the score.
    if next_item_size > 0 && post_residual >= next_item_size {
