    // 4. Harmonic Alignment: Bias towards bins whose residual is close to the mean_residual of all bins.
    // This keeps the bins balanced in terms of remaining capacity.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 5. Progression Weighting: As the stream nears the end, prioritize closing bins over balancing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
