    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (40.0 + (progress * 60.0));

    // Non-linear coupling: Reward post_residuals that are small, but penalize
    // them heavily if they are close to zero (leaving very little room for future items)
    // proportional to the lookahead next_item_size.
    let tightness_penalty = if post < (next_item_size as f64) && next_item_size > 0 {
