    let variance_penalty = (post - mean_residual).abs() * 0.2;

    // Heuristic: Prefer bins that leave just enough space for the next item,
    // normalized by the remaining stage of the process.
    let score = post + new_bin_penalty + tightness_penalty + variance_penalty;

