    // 3. Open Bin Pressure: Penalize opening new bins unless necessary.
    // If this is a brand-new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless it is the only option (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Forced to open a new bin
        }
    }

    // 4. Tight Fit Reward: Strongly favor bins that become completely full (Perfect Fit).
    if post_residual == 0 {
        score -= 40.0;
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill rates across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // 2. Lookahead Synergy: Reward bins that become "perfect" matches for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong reward for creating a perfect fit for the next item
        } else if post_residual > next_item_size {
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 20.0; // Penalty if the next item cannot fit in the resulting space
        }
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Heavy penalty for opening a new bin if we have options
        } else {
            score -= 10.0; // Only open new if forced
        }
    }

    // 4. Mean Residual Balancing: Keep open bins tight
    // If post_residual is significantly better than current mean, prioritize it
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize clearing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Avoid "orphan" small spaces: If post_residual is unusable for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
