    // Penalty is squared to discourage fragmented space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead mechanism: If the next item exists, penalize bins that cannot fit it
    // after the current item is placed.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 45.0 * (1.0 - progress);
