    // 3. Global state balance: If we have many open bins, prioritize filling existing ones
    // over opening new ones (penalize new bin creation).
    if is_new_bin {
        score += 30.0 + (open_bins_count as f64 * 2.0);

        // If we are late in the stream, be more aggressive about closing bins.
        if progress > 0.8 {
            score -= 20.0;
        }
    } else {
        // 4. Density reward: Reward bins that are already closer to the mean residual
        // to keep the distribution of remaining space uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // 5. Critical threshold: If this is the only bin that fits the item, reward it to
    // prevent unnecessary new bin allocation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish high post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for opening new bins: scale by progress to be more conservative as the stream ends
    if is_new_bin {
        // High penalty for new bins early on, diminishing slightly as we reach the end
        // if fitting_bins_count > 0, we heavily penalize opening a new bin unnecessarily
        score += (bin_capacity as f64 * 0.8) + (fitting_bins_count as f64 * 50.0 * (1.0 - progress));
    } else {
        // Reward placements that leave a residual close to the mean of other bins to maintain uniformity
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead: If next_item_size is large, penalize small post_residual that would strand the item
        if next_item_size > post_residual && post_residual > 0 {
