        }

        // Non-linear coupling: Avoid creating "dead zones" (small remainders that fit nothing)
        // If post_residual is small but > 0, it's often worse than having 0 residual.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0 * (1.0 - progress);
        }
