pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit (Minimize post_residual)
    // The base score is the post_residual, which inherently favors tight fits.

    // 2. Lookahead Penalty/Reward (Targeting the next item)
    // If we have a next item, we penalize post_residuals that are too small to fit the next item,
    // but reward those that fit it perfectly (near-zero waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item (creating a bin that cannot take the future item)
            score += 40.0;
        } else {
            // Reward for leaving space that closely matches the next item
            let waste = (post_residual - next_item_size) as f64;
            score -= (50.0 - waste).max(0.0) * 0.5;
