    // 3. Penalty for Opening New Bins
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy static penalty 
    // unless it is the only way to fit the item.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 0 {
            score += 50.0; // Strong disincentive to open new bins if existing ones work
        }
    }

    // 4. Mean Residual Balancing
    // If the post_residual is significantly higher than the current mean, we penalize the bin
    // to encourage packing into more "efficient" bins, preventing fragmentation.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression Scaling
    // As we approach the end of the stream, prioritize clearing remaining capacity.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
