    // Lookahead logic: if next_item_size is large, prioritize bins where post_residual >= next_item_size.
    // If post_residual is too small to fit the next item, penalize it quadratically.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post).powf(1.5)
    } else {
        0.0
    };

    // Heavily penalize opening a new bin if an existing bin could fit the item (fitting_bins_count > 0).
    let fit_constraint = if is_new_bin > 0.0 && fitting_bins_count > 0 {
        1000.0
    } else {
        0.0
    };

    // Combine: Minimize post_residual (Best Fit), but adjust for future packing and stream maturity.
    let score = post 
        + new_bin_penalty 
        + residual_balance 
        + lookahead_penalty 
        + fit_constraint;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
