    }

    // 6. Global state balance: If open_bins_count is high, prioritize bins 
    // that are already quite full (low mean_residual) to consolidate space.
    if mean_residual < 20.0 {
        score += (20.0 - mean_residual) * 0.5;
    }

    // 7. Progression scaling: As we approach the end of the stream, 
    // prioritize filling the most empty bins to minimize the final count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= (1.0 - progress) * 20.0;
