    // 2. Penalty for creating "dead space" (fragments too small for common items).
    // If the post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Dynamic thresholding for new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // existing bins could have taken the item. Only open a new bin if the "fitting_bins_count"
    // is low or the current fit quality is abysmal.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin proportional to the availability of existing space.
        score += (fitting_bins_count as f64) * 15.0;

        // As the stream nears completion, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    // 5. Global state balancing:
    // If the current bin's residual after placing is significantly higher than the mean,
    // penalize it to encourage packing items into bins that are already "fuller".
    if (post_residual as f64) > mean_residual {
