    // If the post_residual is a multiple of common item sizes (e.g., 20, 25), 
    // it is more likely to be filled later. Reward small remainders that are "useful".
    let remainder_mod = (post_residual % 25) as f64;
    score += remainder_mod * 0.8;

    // 3. Lookahead Synergy:
    // If next_item_size fits in the post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a new bin. 
    // Penalize opening a new bin unless the fitting_bins_count is low or 
    // the current item is very large (difficult to place).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have fitting options
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Reward opening if no other choice
            score -= 50.0;
        }
    }

    // 5. Mean Residual Balancing:
    // Avoid creating bins that are significantly worse than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progressive Tightening:
    // As we near the end of the stream, prioritize closing bins (minimize open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit the smallest possible items (assumed ~10),
