    // 4. Mean Residual Balancing: Keep bins balanced relative to the global state.
    // If this bin's post_residual is much larger than the average, penalize to keep bins uniform.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
