        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: Reward if the next item can fit into the remaining space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Pressure: If this is a new bin (bin_residual == bin_capacity)
    // Penalize opening a new bin if other bins can accommodate the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 5.0; // Necessary evil
        }
    }

    // Global efficiency: Favor bins that stay close to the mean_residual
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 20.0;
        }
    }

    // 2. Best-fit logic (tightness is good)
    // We prefer smaller post_residual, but we penalize values that leave "dead space"
    // that is too small for any likely item (below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead matching:
    // If we have a next_item, we want post_residual to be close to next_item_size
    // without going negative.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.5;
        } else {
            // Cannot fit next item, penalize slightly based on how much we missed it by
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 4. Global balance:
    // If the current bin is significantly emptier than the mean, try to fill it.
    // If it's fuller than the mean, try to leave it for smaller items.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.2;

    // 5. Progression:
    // Towards the end of the stream, be more aggressive about filling open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}
